/* Spanish translation of the CompTIA Security+ practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("security-plus", {
  "s1": ["Una empresa instala un mantrap en la entrada de su centro de datos. ¿Qué categoría y tipo de control es este?", ["Técnico, detectivo", "Físico, preventivo", "Gerencial, correctivo", "Operativo, compensatorio"], "Un mantrap detiene físicamente el tailgating antes de que ocurra, así que es un control físico y preventivo.", ["Un mantrap es una barrera física, no un sistema técnico, y detiene la entrada en lugar de solo detectarla después.", null, "Los controles gerenciales son políticas y planes, y los controles correctivos reparan cosas después de un incidente; un mantrap no es ninguno de los dos.", "Los controles operativos los llevan a cabo personas, y un control compensatorio sustituye a uno que falta; un mantrap es una barrera física principal."]],
  "s2": ["Después de un robo, el equipo de seguridad revisa las grabaciones de las cámaras para identificar al intruso. ¿Qué tipo de control cumplen las cámaras?", ["Preventivo", "Correctivo", "Detectivo", "Directivo"], "Revisar grabaciones después de los hechos identifica lo que ocurrió, lo cual es detectivo.", ["Los controles preventivos detienen un incidente antes de que ocurra; las grabaciones revisadas después del robo no detuvieron nada.", "Los controles correctivos restauran sistemas o reparan daños después de un incidente; revisar grabaciones solo identifica lo que ocurrió.", null, "Los controles directivos le indican a las personas qué hacer, como políticas o letreros; las grabaciones no dirigen el comportamiento."]],
  "s3": ["¿Qué tecnología proporciona principalmente el no repudio?", ["Cifrado simétrico", "Firmas digitales", "Hashing por sí solo", "Listas de control de acceso"], "Una firma digital se crea con la clave privada del remitente, así que el remitente no puede negar de forma creíble haberla firmado.", ["El cifrado simétrico usa una clave compartida, así que cualquiera de las partes pudo haber producido un mensaje y ninguna puede probar quién lo envió.", null, "Un hash por sí solo prueba la integridad pero no el origen, porque cualquiera puede calcular el mismo hash sin una clave privada.", "Las ACL controlan quién puede acceder a los recursos; no producen una prueba de que una persona específica envió o firmó algo."]],
  "s4": ["En una arquitectura zero trust, ¿qué componente decide si a un sujeto se le concede acceso a un recurso?", ["Punto de aplicación de políticas (policy enforcement point)", "Motor de políticas (policy engine)", "Zona de confianza implícita", "Plano de datos"], "El motor de políticas (en el plano de control) toma la decisión; el punto de aplicación la ejecuta.", ["El punto de aplicación de políticas ejecuta la decisión permitiendo o bloqueando la conexión, pero no toma la decisión en sí.", null, "Zero trust busca eliminar las zonas de confianza implícita; son algo que se debe reducir, no un componente que toma decisiones.", "El plano de datos transporta el tráfico real hacia los recursos; las decisiones de acceso se toman en el plano de control."]],
  "s5": ["Un equipo despliega un servidor SSH falso que registra cada comando del atacante y luego bloquea la IP de origen. ¿Qué es el servidor falso?", ["Sensor IDS", "Honeypot", "Jump server", "Host en la DMZ"], "Un sistema señuelo diseñado para atraer y registrar atacantes es un honeypot, una tecnología de engaño.", ["Un sensor IDS monitorea el tráfico real en busca de ataques; no es un servidor falso creado para atraer atacantes.", null, "Un jump server es un host real y endurecido que los administradores usan para llegar a zonas seguras, no un señuelo para atacantes.", "Un host en la DMZ es un servidor real expuesto al público en una subred filtrada, no un sistema falso creado deliberadamente para registrar atacantes."]],
  "s6": ["¿Qué parte de la tríada CIA afecta principalmente un ataque DDoS contra el sitio web de la empresa?", ["Confidencialidad", "Integridad", "Disponibilidad", "No repudio"], "Un DDoS impide que los usuarios legítimos lleguen al servicio, lo que es un impacto en la disponibilidad.", ["La confidencialidad consiste en evitar la divulgación no autorizada; un DDoS por sí solo no expone datos.", "La integridad consiste en evitar cambios no autorizados en los datos; un DDoS inunda el servicio en lugar de alterar datos.", null, "El no repudio no forma parte de la tríada CIA; se refiere a la prueba de origen, que un DDoS no afecta."]],
  "s7": ["¿Cuál es el propósito principal del hashing en la seguridad de datos?", ["Cifrar datos para una transmisión segura", "Verificar la integridad de los datos detectando cambios no autorizados", "Comprimir datos", "Almacenar contraseñas de modo que se puedan recuperar"], "El hashing es unidireccional y se usa para la integridad: cualquier cambio en la entrada cambia el hash.", ["El hashing es unidireccional y no se puede revertir, así que no sirve para cifrar datos que deban leerse después.", null, "Un hash tiene longitud fija y no puede recrear los datos originales, así que no es compresión.", "Las contraseñas con hash están pensadas precisamente para que no se puedan recuperar; un almacenamiento recuperable requeriría cifrado."]],
  "s8": ["Agregar datos aleatorios únicos a cada contraseña antes de aplicarle hash defiende principalmente contra:", ["Keyloggers", "Ataques con rainbow tables", "Phishing", "Ataques de repetición (replay)"], "Esos datos aleatorios son un salt; hacen inútiles las rainbow tables precalculadas.", ["Los keyloggers capturan las contraseñas mientras se escriben, antes de cualquier hash, así que un salt no sirve contra ellos.", null, "El phishing engaña a los usuarios para que entreguen su contraseña en texto plano, algo que un salt en el hash almacenado no puede evitar.", "Los ataques de repetición reenvían tráfico de autenticación capturado; las defensas son los nonces y las marcas de tiempo, no los salts de contraseñas."]],
  "s9": ["¿Cuál de estos es un algoritmo de cifrado simétrico?", ["RSA", "ECC", "AES", "Diffie-Hellman"], "AES usa una sola clave compartida. RSA y ECC son asimétricos; Diffie-Hellman es intercambio de claves.", ["RSA es asimétrico: usa un par de claves pública y privada en lugar de una sola clave compartida.", "ECC (criptografía de curva elíptica) es asimétrica y se basa en pares de claves pública y privada.", null, "Diffie-Hellman es un método de intercambio de claves para acordar un secreto compartido, no un algoritmo de cifrado simétrico en sí."]],
  "s10": ["¿Qué técnica hace que una contraseña débil sea más difícil de descifrar al pasarla por muchas rondas de hashing?", ["Key stretching (p. ej., PBKDF2, bcrypt)", "Esteganografía", "Tokenización", "Key escrow (custodia de claves)"], "El key stretching repite el hashing para frenar la fuerza bruta.", [null, "La esteganografía oculta datos dentro de otros archivos, como imágenes; no frena el descifrado de contraseñas.", "La tokenización reemplaza los datos sensibles con tokens aleatorios guardados en una bóveda; no implica rondas repetidas de hashing.", "El key escrow guarda copias de las claves con un tercero de confianza para su recuperación; no fortalece las contraseñas."]],
  "s11": ["Un cambio falla durante la ventana de mantenimiento. ¿Qué documento le indica al administrador cómo volver al estado anterior?", ["Análisis de impacto", "Plan de reversión (backout plan)", "Procedimiento operativo estándar", "Solicitud de cambio"], "El plan de reversión describe cómo deshacer el cambio.", ["Un análisis de impacto evalúa de antemano los riesgos y efectos de un cambio; no da los pasos para deshacerlo.", null, "Un SOP documenta cómo realizar tareas rutinarias, no cómo revertir un cambio específico que falló.", "La solicitud de cambio propone y describe el cambio; los pasos de reversión corresponden al plan de reversión."]],
  "s12": ["¿Qué grupo revisa y aprueba los cambios antes de implementarlos?", ["Equipo de respuesta a incidentes", "Comité asesor de cambios (CAB)", "Red team", "Dueños de los datos"], "El CAB evalúa el riesgo y aprueba o rechaza las solicitudes de cambio.", ["El equipo de respuesta a incidentes maneja incidentes de seguridad, no la revisión y aprobación rutinaria de cambios planificados.", null, "Un red team simula atacantes para probar las defensas; no tiene ningún papel en la aprobación de cambios.", "Los dueños de los datos responden por conjuntos de datos específicos, pero no son el órgano formal que aprueba las solicitudes de cambio."]],
  "s13": ["Una empresa necesita un solo certificado para example.com, example.net y shop.example.org. ¿Qué certificado sirve?", ["Certificado wildcard", "Certificado autofirmado", "Certificado SAN", "Certificado de firma de código"], "Los Subject Alternative Names enumeran varios dominios distintos. Un wildcard solo cubre los subdominios de primer nivel de un dominio.", ["Un wildcard como *.example.com cubre solo los subdominios de un dominio, no dominios distintos como example.net.", "Los navegadores no confían por defecto en un certificado autofirmado, y ser autofirmado no resuelve cubrir varios dominios.", null, "Un certificado de firma de código verifica a los editores de software; no se usa para proteger sitios web en varios dominios."]],
  "s14": ["¿Qué método comprueba en tiempo real el estado de revocación de un certificado sin descargar la lista completa?", ["CRL", "OCSP", "CSR", "Key escrow"], "OCSP consulta al respondedor de la CA el estado de un solo certificado.", ["Una CRL es la lista completa de certificados revocados que los clientes deben descargar, justo lo que la pregunta quiere evitar.", null, "Una CSR es una solicitud que se envía a una CA para que emita un certificado; no tiene nada que ver con el estado de revocación.", "El key escrow guarda copias de claves privadas con un tercero; no comprueba si un certificado está revocado."]],
  "s15": ["¿Qué describe MEJOR cómo se crea una firma digital?", ["Cifrar todo el mensaje con la clave pública del destinatario", "Aplicar hash al mensaje y cifrar el hash con la clave privada del remitente", "Aplicar hash al mensaje y cifrar el hash con la clave pública del destinatario", "Cifrar el mensaje con una clave simétrica compartida"], "Firmar usa la clave privada del remitente sobre el hash; cualquiera puede verificarlo con la clave pública del remitente.", ["Cifrar con la clave pública del destinatario proporciona confidencialidad, no una firma, ya que cualquiera puede usar esa clave pública.", null, "Usar la clave pública del destinatario no prueba nada sobre el remitente; firmar requiere la clave privada del remitente.", "Una clave simétrica compartida proporciona confidencialidad pero no no repudio, porque ambas partes tienen la misma clave."]],
  "s16": ["Una solicitud de firma de certificado (CSR) contiene del solicitante su:", ["Clave privada", "Clave pública", "Certificado raíz", "CRL"], "La CSR lleva la clave pública y la información de identidad; la clave privada nunca sale del solicitante.", ["La clave privada nunca debe salir del solicitante; enviarla a una CA la comprometería.", null, "El certificado raíz pertenece a la CA y no forma parte de la CSR del solicitante.", "Una CRL la publica la CA para enumerar los certificados revocados; no se incluye en una solicitud de firma."]],
  "s17": ["Un centro de datos necesita un dispositivo resistente a manipulaciones para generar y almacenar claves de muchos servidores. ¿Qué debe implementar?", ["TPM", "HSM", "Secure enclave", "Key escrow"], "Un HSM gestiona claves a gran escala; un TPM protege las claves de un solo dispositivo.", ["Un TPM es un chip integrado en un solo dispositivo para proteger las claves de ese dispositivo; no proporciona claves a muchos servidores.", null, "Un secure enclave es un área aislada dentro de un procesador, no un dispositivo compartido para gestionar claves en todo un centro de datos.", "El key escrow es un acuerdo para guardar copias de claves con un tercero, no un dispositivo resistente a manipulaciones para generar claves."]],
  "s18": ["Un administrador necesita reemplazar Telnet en los dispositivos de red. ¿Qué protocolo y puerto debe usar?", ["SSH, 22", "SNMP, 161", "HTTPS, 443", "FTP, 21"], "SSH en TCP 22 es el reemplazo cifrado de Telnet.", [null, "SNMP en UDP 161 sirve para monitorear y gestionar dispositivos, no para sesiones interactivas remotas de línea de comandos.", "HTTPS en el 443 protege el tráfico web; no es el reemplazo estándar del acceso por línea de comandos de Telnet.", "FTP en el puerto 21 transfiere archivos y tampoco está cifrado, así que no corregiría la debilidad de Telnet."]],
  "s19": ["¿Qué puerto usa LDAP sobre TLS (LDAPS) de forma predeterminada?", ["389", "443", "636", "3389"], "LDAPS usa el 636; LDAP sin cifrar usa el 389.", ["El puerto 389 es LDAP sin cifrar, no LDAP sobre TLS.", "El puerto 443 es HTTPS, usado para tráfico web seguro y no para consultas de directorio.", null, "El puerto 3389 es RDP, usado para Escritorio remoto, no para LDAP."]],
  "s20": ["Un atacante envía respuestas falsificadas para que los hosts asocien la IP del gateway con la MAC del atacante. ¿Qué ataque es este?", ["Envenenamiento de DNS", "Envenenamiento de ARP", "Inundación de MAC (MAC flooding)", "Salto de VLAN (VLAN hopping)"], "ARP asocia direcciones IP con MAC; falsificar esas respuestas coloca al atacante en la ruta (on-path).", ["El envenenamiento de DNS corrompe las asociaciones de nombre a IP en las cachés DNS, no las asociaciones de IP a MAC en la red local.", null, "El MAC flooding satura la tabla CAM de un switch para que difunda tramas; no falsifica respuestas sobre la IP del gateway.", "El VLAN hopping permite a un atacante llegar a otras VLAN mediante switch spoofing o doble etiquetado, no falsificando respuestas ARP."]],
  "s21": ["¿Qué le agrega DNSSEC a DNS?", ["Cifrado de las consultas", "Integridad y autenticación de origen de las respuestas DNS", "Balanceo de carga", "Resolución más rápida"], "DNSSEC firma los registros para que los resolvers puedan verificar que no fueron manipulados. No cifra.", ["DNSSEC no cifra las consultas ni las respuestas DNS; el cifrado proviene de DNS over HTTPS o DNS over TLS.", null, "DNSSEC agrega firmas, no distribución de tráfico; el balanceo de carga no tiene relación.", "DNSSEC agrega trabajo de validación de firmas, así que no hace más rápida la resolución."]],
  "s22": ["Un log del firewall muestra conexiones entrantes repetidas a TCP 3389. ¿Qué servicio está siendo atacado?", ["SMB", "SSH", "RDP", "SQL Server"], "TCP 3389 es Remote Desktop Protocol.", ["SMB usa TCP 445 (e históricamente 139), no el 3389.", "SSH usa TCP 22, no el 3389.", null, "SQL Server usa TCP 1433 de forma predeterminada, no el 3389."]],
  "s23": ["Un grupo con abundantes recursos, muy sofisticado y que realiza espionaje a largo plazo contra empresas de telecomunicaciones es MÁS probablemente:", ["Un hacktivista", "Un actor estatal (nation-state)", "Un atacante sin habilidades", "Una amenaza interna"], "Los recursos, la sofisticación y los objetivos de espionaje apuntan a un APT de un Estado, como Salt Typhoon.", ["Los hacktivistas actúan por ideología y suelen buscar una disrupción visible, no un espionaje a largo plazo con abundantes recursos.", null, "Los atacantes sin habilidades usan herramientas existentes con poca sofisticación o financiamiento, lo opuesto a esta descripción.", "Una amenaza interna proviene de dentro de la organización; la pregunta describe un grupo de espionaje externo y con muchos recursos."]],
  "s24": ["¿Qué motiva con MÁS frecuencia a un hacktivista?", ["La ganancia económica", "Creencias filosóficas o políticas", "El espionaje para un gobierno", "La venganza contra un empleador"], "Los hacktivistas actúan por ideología o por causas.", ["La ganancia económica impulsa al crimen organizado y a las bandas de ransomware, no a los hacktivistas.", null, "El espionaje gubernamental es el sello distintivo de los actores estatales, no de los hacktivistas.", "La venganza contra un empleador suele motivar a un empleado descontento, no a un hacktivista."]],
  "s25": ["Un empleado guarda archivos de la empresa en una cuenta personal en la nube que el departamento de TI nunca aprobó. Esto es:", ["Shadow IT", "Sabotaje interno", "Exfiltración de datos por parte de un Estado", "Un ataque watering hole"], "Usar tecnología no aprobada fuera del control de TI es shadow IT.", [null, "El sabotaje interno significa dañar deliberadamente a la organización; guardar archivos por comodidad no tiene la intención de causar daño.", "Nada sugiere un gobierno extranjero; se trata de un empleado que usa un servicio no aprobado.", "Un ataque watering hole compromete un sitio web que visitan los objetivos; no se trata de empleados que usan servicios no aprobados."]],
  "s26": ["Un usuario recibe un mensaje de texto con un enlace que afirma que su cuenta bancaria está bloqueada. Esto es:", ["Vishing", "Smishing", "Whaling", "Pharming"], "El phishing por SMS es smishing; por voz es vishing.", ["El vishing es phishing por voz a través de llamadas telefónicas, no por mensajes de texto.", null, "El whaling apunta específicamente a altos ejecutivos; este es un mensaje de texto genérico a un usuario común.", "El pharming redirige a los usuarios a sitios falsos mediante la manipulación de DNS o del archivo hosts, sin necesidad de un mensaje con enlace."]],
  "s27": ["Unos atacantes comprometen un sitio de noticias que los ingenieros de una empresa objetivo visitan a diario. ¿Qué ataque es este?", ["Typosquatting", "Watering hole", "Pretexting", "Suplantación de marca"], "Infectar un sitio en el que el grupo objetivo ya confía y que visita es un ataque watering hole.", ["El typosquatting registra dominios mal escritos para aprovechar los errores de tipeo; aquí se comprometió un sitio real y legítimo.", null, "El pretexting usa un escenario inventado para convencer a alguien de actuar; este ataque se basa en cambio en un sitio web infectado.", "La suplantación de marca falsifica la identidad de una empresa; aquí se comprometió el propio sitio de noticias real."]],
  "s28": ["Alguien llama diciendo ser del soporte de TI e inventa una historia sobre una actualización fallida para obtener la contraseña de un usuario. Esto es:", ["Pretexting", "Tailgating", "Credential stuffing", "Spear phishing"], "Construir un escenario falso para ganarse la confianza es pretexting.", [null, "El tailgating es seguir a alguien a través de una puerta física protegida, no llamar por teléfono para pedir una contraseña.", "El credential stuffing reutiliza pares de usuario y contraseña filtrados en inicios de sesión automatizados; no implica una llamada telefónica.", "El spear phishing es un mensaje dirigido, normalmente por correo; la característica definitoria aquí es la historia inventada contada por teléfono."]],
  "s29": ["Usuarios no autorizados pueden ver registros de clientes debido a verificaciones de permisos débiles. ¿Qué categoría de OWASP aplica?", ["Configuración de seguridad incorrecta (security misconfiguration)", "Control de acceso roto (broken access control)", "Inyección", "Diseño inseguro"], "Cuando los usuarios pueden llegar a datos o funciones a los que no deberían, se trata de control de acceso roto.", ["La configuración de seguridad incorrecta abarca valores predeterminados y ajustes inseguros; la falla aquí es específicamente la falta de verificaciones de permisos.", null, "La inyección envía entradas maliciosas a un intérprete, como la inyección SQL; aquí no se describe ninguna entrada manipulada.", "El diseño inseguro se refiere a fallas de arquitectura en general; la falta de verificaciones de autorización entra en control de acceso roto."]],
  "s30": ["Un programa verifica los permisos de un archivo y luego un atacante reemplaza el archivo antes de que el programa lo use. Esto es:", ["Un desbordamiento de búfer", "Una condición de carrera (TOCTOU)", "Una fuga de memoria", "Un desbordamiento de enteros"], "El tiempo de verificación a tiempo de uso (time-of-check to time-of-use) es una condición de carrera.", ["Un desbordamiento de búfer escribe más allá del final de un búfer de memoria; no depende del tiempo entre una verificación y un uso.", null, "Una fuga de memoria ocurre cuando un programa no libera memoria y agota lentamente los recursos; no se trata de reemplazar archivos.", "Un desbordamiento de enteros ocurre cuando un número supera el máximo de su tipo y da la vuelta; no es un problema de tiempos."]],
  "s31": ["Un desbordamiento de búfer le permite a un atacante ejecutar código que le otorga control administrativo. ¿Qué impacto es este?", ["Manipulación de datos", "Escalamiento de privilegios", "Sobrecarga del sistema", "Evasión del cifrado"], "Obtener acceso de administrador o root a partir de un acceso menor es escalamiento de privilegios.", ["La manipulación de datos significa alterar datos; el impacto descrito aquí es obtener control administrativo.", null, "La sobrecarga del sistema es un resultado de denegación de servicio; ejecutar código para obtener derechos de administrador no es sobrecarga.", "La evasión del cifrado significa eludir la protección criptográfica; aquí no interviene ningún cifrado."]],
  "s32": ["¿Cuál es la defensa MÁS eficaz contra la inyección SQL?", ["Solo límites de longitud de entrada", "Consultas parametrizadas", "Desactivar HTTPS", "Validación con JavaScript del lado del cliente"], "Las sentencias preparadas (prepared statements) impiden que la entrada se ejecute como SQL.", ["Los límites de longitud se pueden evadir con cargas de inyección cortas y no impiden que la entrada se ejecute como SQL.", null, "Desactivar HTTPS solo elimina el cifrado del transporte y no tiene nada que ver con prevenir la inyección SQL.", "La validación con JavaScript del lado del cliente se evade fácilmente enviando solicitudes directamente al servidor."]],
  "s33": ["Un script malicioso guardado en una reseña de producto se ejecuta en el navegador de cada visitante. ¿Qué es esto?", ["XSS reflejado", "XSS almacenado", "CSRF", "SSRF"], "Un script almacenado en el servidor y servido a todos los visitantes es XSS almacenado (persistente).", ["El XSS reflejado rebota el script en el servidor dentro de una sola solicitud manipulada; no queda guardado para cada visitante.", null, "CSRF engaña al navegador de un usuario con sesión iniciada para que envíe solicitudes no deseadas; no almacena scripts en el contenido de la página.", "SSRF hace que el servidor envíe solicitudes a recursos internos; no ejecuta scripts en los navegadores de los visitantes."]],
  "s34": ["Antes del lanzamiento, los desarrolladores analizan cómo podrían los atacantes explotar una aplicación y priorizan las correcciones. ¿Qué proceso es este?", ["Análisis de transferencia de riesgo", "Respuesta a incidentes", "Modelado de amenazas", "Prueba de penetración"], "Mapear de forma proactiva las rutas de ataque y priorizar las mitigaciones es modelado de amenazas.", ["La transferencia de riesgo traslada el impacto financiero a un tercero, como una aseguradora; no mapea cómo podrían los atacantes explotar una aplicación.", "La respuesta a incidentes reacciona a ataques que ya ocurrieron, no es un análisis previo al lanzamiento.", null, "Una prueba de penetración explota activamente un sistema ya construido; mapear rutas de ataque y priorizar correcciones durante el diseño es modelado de amenazas."]],
  "s35": ["Un atacante construye una URL que hace que el servidor solicite por HTTP la dirección interna localhost/admin. ¿Qué vulnerabilidad es esta?", ["CSRF", "SSRF", "Directory traversal (recorrido de directorios)", "Inyección SQL"], "Se engaña al servidor para que haga solicitudes a recursos internos: falsificación de solicitudes del lado del servidor (server-side request forgery).", ["CSRF hace que el navegador de una víctima envíe solicitudes no deseadas; aquí es el propio servidor al que se engaña para que haga la solicitud.", null, "El directory traversal usa secuencias ../ para leer archivos fuera de la raíz web, no para hacer que el servidor solicite URL.", "La inyección SQL ataca las consultas a la base de datos; este ataque hace que el servidor obtenga una URL interna."]],
  "s36": ["Un malware se propaga por la red por sí solo, sin ninguna acción del usuario. ¿Qué es?", ["Troyano", "Gusano (worm)", "Bomba lógica", "Spyware"], "Los gusanos se autorreplican a través de las redes; los troyanos necesitan que un usuario los ejecute.", ["Un troyano se disfraza de software legítimo y necesita que un usuario lo ejecute; no se propaga por sí solo.", null, "Una bomba lógica permanece inactiva hasta que una condición la activa y no se replica por la red.", "El spyware recopila información en secreto de un sistema, pero no se define por propagarse por las redes."]],
  "s37": ["Un código plantado por un desarrollador borra la base de datos de nómina si su nombre se elimina de los registros de Recursos Humanos. Esto es:", ["Un rootkit", "Una bomba lógica", "Un keylogger", "Un RAT"], "El código malicioso que se activa por una condición o una fecha es una bomba lógica.", ["Un rootkit se oculta y mantiene acceso privilegiado; no se define por un disparador basado en una condición.", null, "Un keylogger registra las pulsaciones de teclas; no borra datos cuando se cumple una condición.", "Un RAT le da a un atacante control remoto de un sistema; no es código plantado que espera una condición."]],
  "s38": ["Los logs muestran un intento fallido de inicio de sesión en cada una de 400 cuentas diferentes con la contraseña Winter2026!. ¿Qué ataque es este?", ["Fuerza bruta", "Password spraying", "Credential stuffing", "Pass the hash"], "Probar unas pocas contraseñas comunes en muchas cuentas evita los bloqueos: es password spraying.", ["La fuerza bruta prueba muchas contraseñas contra una sola cuenta, lo que activaría rápidamente los bloqueos; aquí es una contraseña en muchas cuentas.", null, "El credential stuffing usa pares de usuario y contraseña filtrados de otras brechas, no una contraseña común contra todas las cuentas.", "Pass the hash reutiliza un hash de contraseña robado para autenticarse; no implica adivinar contraseñas."]],
  "s39": ["Un usuario inicia sesión desde Dallas y, 10 minutos después, desde Moscú. ¿Qué indicador es este?", ["Consumo de recursos", "Viaje imposible", "Bloqueo de cuenta", "Registro fuera de ciclo"], "Inicios de sesión desde ubicaciones demasiado alejadas para el tiempo transcurrido indican un viaje imposible.", ["Los indicadores de consumo de recursos son un uso inusual de CPU, memoria, disco o ancho de banda, no las ubicaciones de inicio de sesión.", null, "El bloqueo de cuenta proviene de intentos fallidos repetidos; estos fueron inicios de sesión exitosos desde lugares distantes.", "El registro fuera de ciclo significa logs creados en momentos inesperados; la pista clave aquí es la distancia geográfica en poco tiempo."]],
  "s40": ["Un atacante obliga a un cliente y un servidor a negociar una versión más antigua y débil de TLS. Esto es:", ["Un ataque de cumpleaños", "Un ataque de degradación (downgrade)", "Un ataque de repetición (replay)", "Un ataque de colisión"], "Forzar protocolos o cifrados más débiles es un ataque de degradación.", ["Un ataque de cumpleaños aprovecha la probabilidad de colisiones de hash; no fuerza una versión de protocolo más antigua.", null, "Un ataque de repetición reenvía tráfico válido capturado; no cambia qué versión de protocolo se negocia.", "Un ataque de colisión encuentra dos entradas con el mismo hash; no manipula la negociación de TLS."]],
  "s41": ["¿Qué malware es MÁS probable que oculte su presencia modificando el kernel del sistema operativo?", ["Adware", "Rootkit", "Gusano", "Ransomware"], "Los rootkits se ocultan a bajo nivel, a menudo en el kernel.", ["El adware muestra anuncios no deseados y suele ser visible para el usuario, no se oculta en el kernel.", null, "Un gusano se define por autorreplicarse a través de las redes, no por ocultarse mediante cambios en el kernel.", "El ransomware se da a conocer cifrando archivos y exigiendo un pago; no busca permanecer oculto."]],
  "s42": ["¿Qué mitigación limita MEJOR el movimiento lateral de un atacante después de que se compromete una estación de trabajo?", ["Contraseñas más robustas", "Segmentación de red", "Cifrado de disco completo", "Capacitación de concientización de seguridad"], "La segmentación confina al atacante a una sola zona.", ["Las contraseñas más robustas dificultan el compromiso inicial, pero una vez tomada una estación de trabajo hacen poco para contener el movimiento.", null, "El cifrado de disco completo protege los datos en reposo de un dispositivo perdido o robado, no el tráfico entre sistemas en una red en funcionamiento.", "La capacitación de concientización reduce la probabilidad del primer compromiso, pero no contiene técnicamente al atacante después."]],
  "s43": ["¿Qué control permite que solo se ejecuten ejecutables aprobados previamente en un quiosco?", ["Lista de bloqueo (block list)", "Lista de aplicaciones permitidas (allow list)", "Sandboxing", "Firewall basado en host"], "La lista de permitidos bloquea todo lo que no esté aprobado explícitamente.", ["Una lista de bloqueo solo detiene programas maliciosos conocidos y permite todo lo demás, lo opuesto a permitir solo ejecutables aprobados.", null, "El sandboxing ejecuta programas aislados para limitar el daño; no restringe qué ejecutables pueden correr.", "Un firewall basado en host filtra el tráfico de red, no qué programas pueden ejecutarse."]],
  "s44": ["Un dispositivo médico no se puede parchear porque el fabricante ya no le da soporte. ¿Cuál es el MEJOR enfoque?", ["Aceptar el riesgo y no hacer nada", "Aislarlo en su propio segmento como control compensatorio", "Reemplazar su sistema operativo por tu cuenta", "Desactivar su registro de eventos"], "El aislamiento es un control compensatorio cuando no es posible aplicar parches.", ["No hacer nada deja expuesto un dispositivo con vulnerabilidades conocidas cuando existe un control compensatorio razonable.", null, "Modificar por tu cuenta el sistema operativo de un dispositivo médico podría dañarlo, anular su certificación y crear riesgos para la seguridad de los pacientes.", "Desactivar el registro reduce la visibilidad y dificulta monitorear el dispositivo, lo opuesto a lo que se necesita."]],
  "s45": ["Desactivar los puertos y servicios que no se usan y cambiar las contraseñas predeterminadas son ejemplos de:", ["Hardening (endurecimiento)", "Desmantelamiento (decommissioning)", "Tokenización", "Threat hunting (búsqueda de amenazas)"], "Reducir la superficie de ataque de un sistema es hardening.", [null, "El desmantelamiento significa retirar y desechar un sistema, no reducir la superficie de ataque de uno que sigue en uso.", "La tokenización reemplaza datos sensibles con tokens; no implica cerrar puertos ni cambiar contraseñas predeterminadas.", "El threat hunting busca de forma proactiva atacantes ocultos; no configura sistemas."]],
  "s46": ["Darles a los usuarios solo el acceso que necesitan para su trabajo es el principio de:", ["Separación de funciones", "Mínimo privilegio", "Confianza implícita", "Rotación de puestos"], "El mínimo privilegio minimiza el daño de las cuentas comprometidas o usadas con descuido.", ["La separación de funciones divide las tareas críticas entre personas para que nadie pueda completarlas solo; no se trata del acceso mínimo.", null, "La confianza implícita asume que los usuarios o dispositivos son confiables por defecto, lo opuesto a limitar el acceso.", "La rotación de puestos mueve periódicamente a las personas entre roles para detectar fraudes; no define cuánto acceso recibe un rol."]],
  "s47": ["En una implementación IaaS, ¿quién es responsable de aplicar parches al sistema operativo invitado?", ["El proveedor de la nube", "El cliente", "El fabricante del hipervisor", "El proveedor de servicios de internet"], "En IaaS el proveedor protege el hardware y el hipervisor; el cliente protege el sistema operativo y lo que está por encima.", ["En IaaS el proveedor protege el hardware físico y el hipervisor, pero el sistema operativo invitado es trabajo del cliente.", null, "El fabricante del hipervisor suministra el software de virtualización y no gestiona los sistemas operativos invitados de los clientes.", "Un ISP solo proporciona conectividad y no tiene ningún papel en parchear cargas de trabajo en la nube."]],
  "s48": ["Un atacante sale de una máquina virtual para acceder al hipervisor. Esto es:", ["VM sprawl", "VM escape", "Container drift", "Reversión de snapshot"], "Escapar de un invitado hacia el host es un VM escape.", ["El VM sprawl es tener demasiadas VM sin gestionar; no es un ataque que salga hacia el hipervisor.", null, "El container drift es cuando un contenedor en ejecución cambia respecto de su imagen original; no se trata de escapar de una VM.", "La reversión de snapshot restaura una VM a un estado anterior; es una función de administración, no un ataque."]],
  "s49": ["¿Cuál es un beneficio de seguridad clave de Infrastructure as Code (IaC)?", ["Elimina la necesidad de aplicar parches", "Despliegues consistentes y repetibles que reducen los errores de configuración", "Cifra todo el tráfico automáticamente", "Elimina el modelo de responsabilidad compartida"], "Las plantillas despliegan la misma configuración revisada cada vez.", ["IaC no elimina los parches; los sistemas desplegados y las plantillas siguen necesitando actualizaciones.", null, "IaC define la infraestructura en código, pero no cifra el tráfico automáticamente; el cifrado debe configurarse.", "El modelo de responsabilidad compartida sigue aplicando con IaC; el cliente sigue siendo responsable de lo que despliega."]],
  "s50": ["¿Por qué las redes ICS/SCADA suelen estar aisladas físicamente (air-gapped) o muy segmentadas?", ["Requieren un gran ancho de banda", "La disponibilidad es crítica y a menudo no se pueden parchear rápidamente", "Solo usan conexiones inalámbricas", "Son nativas de la nube"], "Los sistemas industriales priorizan la disponibilidad y a menudo ejecutan software heredado.", ["Las necesidades de ancho de banda no tienen que ver con el aislamiento; el tráfico ICS suele ser de datos de control de poco ancho de banda.", null, "ICS/SCADA suele usar protocolos seriales o industriales cableados, y ser solo inalámbrico no explicaría el aislamiento físico de todos modos.", "Los sistemas ICS/SCADA suelen ser sistemas heredados locales (on-premises), no nativos de la nube."]],
  "s51": ["Un equipo restaura una VM de laboratorio al estado en que estaba antes de una prueba de malware. ¿Qué función usó?", ["Snapshot", "Imagen de contenedor", "Clustering", "Balanceo de carga"], "Los snapshots permiten volver a un estado anterior.", [null, "Una imagen de contenedor es una plantilla para lanzar contenedores; no restaura una VM existente a un estado anterior.", "El clustering agrupa servidores para la disponibilidad y la conmutación por error; no regresa una VM en el tiempo.", "El balanceo de carga reparte el tráfico entre servidores; no tiene capacidad de reversión."]],
  "s52": ["¿Qué dispositivo se ubica en línea (inline) y puede bloquear activamente el tráfico malicioso?", ["IDS", "IPS", "SIEM", "Network tap"], "Un IPS está en línea y puede descartar tráfico; un IDS solo alerta.", ["Un IDS suele observar una copia del tráfico fuera de banda y solo alerta; no bloquea el tráfico.", null, "Un SIEM recopila y correlaciona logs; no es un dispositivo en línea que descarte paquetes.", "Un network tap copia el tráfico de forma pasiva para monitoreo y no puede bloquear nada."]],
  "s53": ["El control de acceso a la red basado en puertos que autentica los dispositivos mediante un servidor RADIUS antes de otorgar el acceso es:", ["802.11", "802.3", "802.1X", "802.15"], "802.1X usa un suplicante, un autenticador y un servidor de autenticación.", ["802.11 es el estándar de Wi-Fi; define las redes inalámbricas, no la autenticación basada en puertos.", "802.3 es Ethernet; define las redes cableadas, no el control de acceso respaldado por RADIUS.", null, "802.15 cubre las redes inalámbricas de área personal como Bluetooth, no el control de acceso a la red."]],
  "s54": ["Un firewall falla y bloquea todo el tráfico hasta que se repara. Esto es:", ["Fail-open", "Fail-closed", "Activo-activo", "Con balanceo de carga"], "Fail-closed prioriza la seguridad sobre la disponibilidad.", ["Fail-open deja pasar todo el tráfico cuando el dispositivo falla, priorizando la disponibilidad sobre la seguridad.", null, "Activo-activo significa que varios dispositivos comparten la carga al mismo tiempo; no es un modo de falla que bloquee todo.", "El balanceo de carga reparte el tráfico entre dispositivos; no describe bloquear todo cuando uno falla."]],
  "s55": ["¿Qué dispositivo está diseñado para proteger las aplicaciones web contra la inyección SQL y el XSS en la capa 7?", ["Filtro de paquetes", "WAF", "Proxy ARP", "Concentrador VPN"], "Un web application firewall inspecciona el tráfico HTTP en busca de ataques a aplicaciones.", ["Un filtro de paquetes revisa encabezados de capa 3/4, como direcciones IP y puertos, y no puede ver la inyección SQL ni el XSS en el contenido HTTP.", null, "Proxy ARP responde solicitudes ARP en nombre de otros hosts; no ofrece protección a aplicaciones web.", "Un concentrador VPN termina muchos túneles VPN; no inspecciona el tráfico web en busca de ataques a aplicaciones."]],
  "s56": ["Los administradores deben conectarse a los servidores de una zona segura a través de un solo host endurecido y monitoreado. Ese host es un:", ["Jump server", "Honeypot", "Proxy inverso", "Balanceador de carga"], "Un jump server (bastion host) es el punto de entrada controlado.", [null, "Un honeypot es un señuelo pensado para atraer atacantes, no una ruta confiable para los administradores.", "Un proxy inverso se ubica delante de los servidores web para atender solicitudes de clientes, no para el acceso administrativo a una zona segura.", "Un balanceador de carga reparte el tráfico de clientes entre servidores; no es un punto de entrada administrativo endurecido."]],
  "s57": ["¿Qué enfoque combina SD-WAN con servicios de seguridad entregados desde la nube, como CASB y el acceso zero trust?", ["NAC", "SASE", "UTM", "SCADA"], "Secure Access Service Edge une redes y seguridad en la nube.", ["NAC controla qué dispositivos pueden unirse a una red; no es una combinación entregada desde la nube de SD-WAN y servicios de seguridad.", null, "UTM combina varias funciones de seguridad en un solo dispositivo local, no SD-WAN más seguridad entregada desde la nube.", "SCADA es tecnología de sistemas de control industrial y no tiene relación con la arquitectura de seguridad en la nube."]],
  "s58": ["Un sistema de pagos reemplaza los números de tarjeta con valores aleatorios asociados a los números reales en una bóveda segura. Esto es:", ["Enmascaramiento", "Tokenización", "Hashing", "Esteganografía"], "La tokenización cambia los datos por tokens que solo se pueden recuperar a través de la bóveda.", ["El enmascaramiento oculta parte de los datos (como mostrar solo los últimos cuatro dígitos), pero no los asocia a una bóveda para recuperarlos.", null, "El hashing es unidireccional y no tiene consulta a una bóveda, así que no se puede recuperar el número de tarjeta real a partir de él.", "La esteganografía oculta datos dentro de otros medios; no sustituye los números de tarjeta con valores aleatorios."]],
  "s59": ["Los datos que se están procesando en la RAM de un servidor, ¿en qué estado están?", ["En reposo", "En tránsito", "En uso", "Archivados"], "Los datos que se están procesando activamente están en uso.", ["Los datos en reposo están almacenados en disco u otro medio y no se están procesando activamente en la RAM.", "Los datos en tránsito se mueven a través de una red, no se procesan en memoria.", null, "Los datos archivados son datos en reposo almacenados a largo plazo, no datos que se estén procesando en este momento."]],
  "s60": ["¿Qué estrategia de respaldo requiere solo el último respaldo completo y otro conjunto más para restaurar?", ["Completo + incremental", "Completo + diferencial", "Solo incremental", "Solo snapshots"], "Un diferencial contiene todos los cambios desde el último completo.", ["Completo más incremental necesita el respaldo completo y cada incremental posterior, que pueden ser muchos conjuntos.", null, "Solo incremental no tiene una base completa, así que restaurar requiere cada conjunto incremental, si es que es posible.", "Los snapshots son capturas de una VM o del almacenamiento en un punto en el tiempo, no una rotación de respaldo de completo más un conjunto."]],
  "s61": ["¿Qué sitio de recuperación puede asumir las operaciones casi de inmediato?", ["Cold site (sitio frío)", "Warm site (sitio tibio)", "Hot site (sitio caliente)", "Sitio móvil"], "Los hot sites están totalmente equipados y con datos actualizados.", ["Un cold site tiene espacio y energía, pero poco o ningún equipo o datos, así que ponerlo en marcha toma días o semanas.", "Un warm site tiene algo de equipo, pero necesita cargar datos actualizados y trabajo de configuración, así que no puede asumir las operaciones de inmediato.", null, "Un sitio móvil es una instalación portátil que debe trasladarse y configurarse antes de usarse, no una toma de control instantánea."]],
  "s62": ["La cantidad máxima de datos que una organización puede permitirse perder, medida en tiempo, es el:", ["RTO", "RPO", "MTTR", "MTBF"], "El objetivo de punto de recuperación define la pérdida de datos aceptable.", ["El RTO es cuánto tiempo puede estar caída una función antes de que deba restaurarse, no cuántos datos se pueden perder.", null, "El MTTR es el tiempo promedio para reparar un componente que falló; no mide la pérdida de datos aceptable.", "El MTBF es el tiempo promedio entre fallas, una medida de confiabilidad sin relación con la pérdida de datos."]],
  "s63": ["Un servidor web está saturado por un DDoS. ¿Qué componente se debe escalar PRIMERO para absorber y distribuir el tráfico?", ["El servidor de base de datos", "El balanceador de carga", "El código de la aplicación", "El servidor de respaldo"], "El balanceador de carga está al frente y distribuye el tráfico entrante.", ["La base de datos está detrás de la capa web, así que escalarla no absorbe ni reparte la avalancha entrante.", null, "Cambiar el código de la aplicación es lento y no reparte las solicitudes entrantes entre servidores.", "Los servidores de respaldo son para la recuperación; escalarlos no ayuda a manejar el tráfico en vivo."]],
  "s64": ["¿Qué función de WPA3 reemplaza el handshake con clave precompartida para resistir ataques de diccionario fuera de línea?", ["TKIP", "SAE", "WEP", "WPS"], "Simultaneous Authentication of Equals protege el handshake.", ["TKIP es un protocolo de cifrado heredado de WPA, no un reemplazo del handshake en WPA3, y hoy está obsoleto por inseguro.", null, "WEP es un estándar de cifrado Wi-Fi antiguo y roto, no una función de WPA3.", "WPS es una función de configuración por comodidad con debilidades conocidas en su PIN; no reemplaza el handshake con PSK."]],
  "s65": ["La información de amenazas muestra que el impacto de una vulnerabilidad depende en gran medida de la configuración de tu sistema. ¿Qué puntuación de CVSS ajustas?", ["Base", "Temporal", "Ambiental (environmental)", "Explotabilidad"], "La puntuación ambiental adapta la severidad a tu entorno.", ["La puntuación base describe las características inherentes de una vulnerabilidad y no cambia según tu configuración.", "La puntuación temporal cambia con el tiempo según la disponibilidad de exploits y el estado de los parches, no según la configuración de tu sistema.", null, "La explotabilidad es una subpuntuación dentro de las métricas base, no la puntuación que ajustas para tu propio entorno."]],
  "s66": ["Un escáner reporta una vulnerabilidad que en realidad no existe en el sistema. Esto es un:", ["Verdadero positivo", "Falso positivo", "Falso negativo", "Verdadero negativo"], "Reportado pero no real es un falso positivo.", ["Un verdadero positivo es una vulnerabilidad reportada correctamente que realmente existe.", null, "Un falso negativo es una vulnerabilidad real que el escáner no detectó, lo opuesto a esta situación.", "Un verdadero negativo reporta correctamente que no hay vulnerabilidad donde no existe ninguna."]],
  "s67": ["¿Por qué ejecutar un escaneo de vulnerabilidades con credenciales?", ["Es más rápido y silencioso", "Ve el software instalado y las configuraciones, lo que da resultados más precisos", "No requiere permiso", "Explota las vulnerabilidades automáticamente"], "Iniciar sesión revela detalles que un escaneo externo no puede ver.", ["Los escaneos con credenciales suelen tardar más y generar más actividad, ya que inspeccionan el sistema a fondo.", null, "Todo escaneo de vulnerabilidades requiere autorización, sea con credenciales o sin ellas.", "Los escaneos de vulnerabilidades identifican debilidades, pero no las explotan; la explotación forma parte de las pruebas de penetración."]],
  "s68": ["Un pentester investiga a una empresa usando WHOIS, ofertas de empleo y LinkedIn sin tocar sus sistemas. Esto es:", ["Reconocimiento activo", "Reconocimiento pasivo", "Escaneo de vulnerabilidades", "Pivoting"], "Sin interacción directa con el objetivo, se trata de reconocimiento pasivo (OSINT).", ["El reconocimiento activo interactúa directamente con los sistemas objetivo, por ejemplo escaneándolos, lo cual no ocurrió aquí.", null, "El escaneo de vulnerabilidades envía sondeos a los sistemas del objetivo, lo cual es interacción directa.", "El pivoting consiste en usar un host comprometido para llegar a otros sistemas, lo que ocurre después del acceso inicial."]],
  "s69": ["¿Qué escaneo de nmap envía paquetes SYN y nunca completa el handshake TCP?", ["-sT", "-sS", "-sU", "-sV"], "-sS es el escaneo SYN semiabierto; -sT completa la conexión.", ["-sT es un escaneo TCP connect que completa el handshake de tres vías.", null, "-sU es un escaneo UDP y no involucra paquetes TCP SYN.", "-sV detecta versiones de servicios y necesita conexiones completas para comunicarse con el servicio."]],
  "s70": ["La empresa compra teléfonos y permite que los empleados también los usen para aplicaciones personales. ¿Qué modelo de implementación es este?", ["BYOD", "COPE", "CYOD", "VDI"], "Propiedad corporativa, habilitado para uso personal (corporate-owned, personally enabled).", ["BYOD significa que los empleados usan sus propios dispositivos personales, pero aquí la empresa compra los teléfonos.", null, "CYOD significa que los empleados eligen entre modelos aprobados, y el enfoque está en la elección más que en el uso personal de un teléfono de la empresa.", "VDI aloja escritorios de forma centralizada y los transmite a los dispositivos; no es un modelo de propiedad de teléfonos."]],
  "s71": ["¿Qué hace un SIEM además de recopilar logs?", ["Cifra los endpoints", "Correlaciona eventos de distintas fuentes y genera alertas", "Bloquea el malware en los hosts", "Reemplaza al firewall"], "La correlación y las alertas a partir de muchas fuentes de logs son el valor central del SIEM.", ["Un SIEM no cifra los endpoints; eso lo hacen las herramientas de cifrado de disco o de archivos.", null, "Bloquear el malware en los hosts es trabajo del antivirus o del EDR, no del SIEM.", "Un SIEM analiza los logs de los firewalls, pero no filtra tráfico ni los reemplaza."]],
  "s72": ["Después de configurar los mecanismos de registro (logging), ¿cuál es la siguiente etapa del proceso de monitoreo?", ["Implementar alertas", "Identificar objetivos", "Usar el registro centralizado", "Monitoreo en tiempo real"], "Objetivos → registro → centralizar → monitorear → alertar.", ["Las alertas van al final de la secuencia, después de centralizar los logs y configurar el monitoreo en tiempo real.", "Identificar los objetivos es la primera etapa de todas, antes de configurar el registro.", null, "El monitoreo en tiempo real viene después de centralizar los logs, así que no es el paso siguiente a configurar el registro."]],
  "s73": ["¿Qué control de correo electrónico les indica a los servidores receptores qué hacer cuando fallan las verificaciones SPF o DKIM?", ["DMARC", "S/MIME", "TLS", "DNSSEC"], "DMARC publica la política y habilita los reportes.", [null, "S/MIME firma y cifra mensajes de correo individuales; no les indica a los servidores cómo manejar las fallas de SPF o DKIM.", "TLS cifra el correo en tránsito entre servidores; no publica una política para las verificaciones de remitente fallidas.", "DNSSEC autentica los registros DNS; no define cómo manejar el correo que no pasa SPF o DKIM."]],
  "s74": ["Una aplicación de ejercicio obtiene permiso para leer tu calendario sin conocer tu contraseña. ¿Qué protocolo lo permite?", ["SAML", "OAuth", "LDAP", "Kerberos"], "OAuth es autorización delegada.", ["SAML se usa principalmente para la autenticación SSO web entre proveedores de identidad y servicios, no para otorgar a una aplicación acceso delegado a tus datos.", null, "LDAP es un protocolo de acceso a directorios; no permite que aplicaciones de terceros accedan a tus datos sin tu contraseña.", "Kerberos es un protocolo de autenticación basado en tickets para redes internas, no de acceso delegado para aplicaciones de terceros."]],
  "s75": ["Los administradores obtienen derechos elevados solo durante la ventana aprobada en que los necesitan. Esto es:", ["Acceso just-in-time (PAM)", "Acceso basado en roles", "Control de acceso obligatorio", "Federación"], "El acceso privilegiado JIT reduce los derechos de administrador permanentes.", [null, "El acceso basado en roles asigna permisos según los roles laborales; esos derechos son permanentes, no limitados en el tiempo.", "El control de acceso obligatorio usa etiquetas y autorizaciones definidas por el sistema; no otorga elevaciones con límite de tiempo.", "La federación permite confiar en identidades entre organizaciones; no limita los derechos de administrador a una ventana de tiempo."]],
  "s76": ["¿Qué factor de autenticación es un escaneo de huella dactilar?", ["Algo que sabes", "Algo que tienes", "Algo que eres", "Algún lugar donde estás"], "La biometría es algo que eres.", ["Algo que sabes se refiere a una contraseña o un PIN, no a un rasgo físico.", "Algo que tienes se refiere a un token, un teléfono o una tarjeta inteligente, no a un dato biométrico.", null, "Algún lugar donde estás se basa en la ubicación, como GPS o IP, no en una huella dactilar."]],
  "s77": ["¿Qué herramienta monitorea los endpoints en busca de comportamiento sospechoso y puede aislar un host automáticamente?", ["DLP", "EDR", "NAC", "WAF"], "Endpoint detection and response vigila el comportamiento de los hosts y responde.", ["DLP detecta y bloquea la salida de datos sensibles de la organización; no busca comportamientos sospechosos en los endpoints.", null, "NAC controla qué dispositivos pueden conectarse a la red; no monitorea de forma continua el comportamiento de los endpoints.", "Un WAF protege aplicaciones web en la capa 7, no endpoints individuales."]],
  "s78": ["Un analista aisló de la red un host infectado. ¿Cuál es la siguiente fase de respuesta a incidentes?", ["Detección", "Erradicación", "Lecciones aprendidas", "Preparación"], "Después de la contención viene la erradicación (eliminar la amenaza) y luego la recuperación.", ["La detección ocurrió antes de la contención; la amenaza ya fue encontrada y aislada.", null, "Las lecciones aprendidas van al final, después de la erradicación y la recuperación.", "La preparación ocurre antes de cualquier incidente, no después de que un host ya fue contenido."]],
  "s79": ["¿Qué se debe recopilar PRIMERO en una investigación forense?", ["La imagen del disco duro", "El contenido de la RAM", "Las cintas de respaldo", "Los logs impresos"], "Orden de volatilidad: la memoria es lo primero que desaparece.", ["Una imagen de disco es menos volátil que la RAM, así que se recopila después de la memoria.", null, "Las cintas de respaldo están entre las fuentes menos volátiles y se recopilan mucho después.", "Los logs impresos no son volátiles en absoluto y se recopilarían al final."]],
  "s80": ["La documentación de todas las personas que manejaron la evidencia y en qué momento es la:", ["Retención legal (legal hold)", "Cadena de custodia", "Solicitud de e-discovery", "Informe de incidente"], "La cadena de custodia preserva la integridad de la evidencia.", ["Una retención legal preserva datos para un litigio; no registra quién manejó la evidencia.", null, "Una solicitud de e-discovery pide que se entregue información electrónica para un proceso legal; no es el registro de manejo.", "Un informe de incidente resume lo ocurrido y la respuesta; no da seguimiento a la custodia de la evidencia."]],
  "s81": ["El asesor legal le indica a TI que preserve todo el correo relacionado con una demanda. Esto es:", ["Una retención legal (legal hold)", "Un derecho de auditoría", "Una política de retención de datos", "Una cadena de custodia"], "Una retención legal suspende la eliminación normal.", [null, "Una cláusula de derecho de auditoría permite que un cliente revise los controles de un proveedor; no preserva el correo para una demanda.", "Una política de retención de datos fija los plazos normales de conservación y eliminación; una retención legal la anula durante el litigio.", "La cadena de custodia documenta quién manejó la evidencia; no es la instrucción de preservar datos."]],
  "s82": ["¿Qué tecnología ejecuta playbooks automatizados para responder a alertas en distintas herramientas?", ["SIEM", "SOAR", "IDS", "DLP"], "La orquestación, automatización y respuesta de seguridad (SOAR) ejecuta playbooks.", ["Un SIEM recopila y correlaciona logs y genera alertas, pero por sí solo no ejecuta playbooks de respuesta automatizados.", null, "Un IDS detecta tráfico sospechoso y alerta; no coordina respuestas entre herramientas.", "DLP previene la pérdida de datos sensibles; no ejecuta playbooks de respuesta entre herramientas de seguridad."]],
  "s83": ["Los líderes recorren un escenario de ransomware en una sala de juntas sin tocar los sistemas. Esto es:", ["Una prueba de penetración", "Un ejercicio de mesa (tabletop)", "Una prueba de conmutación por error (failover)", "Un ejercicio de red team"], "Los recorridos basados en discusión son ejercicios de mesa.", ["Una prueba de penetración ataca activamente sistemas reales, mientras que este ejercicio es solo de discusión.", null, "Una prueba de failover realmente cambia los sistemas a los respaldos, lo cual sí toca los sistemas.", "Un ejercicio de red team es un ataque simulado práctico contra sistemas reales, no una discusión en una sala de juntas."]],
  "s84": ["Una empresa contrata un seguro cibernético para cubrir los costos de una brecha. ¿Qué tratamiento del riesgo es este?", ["Aceptar", "Evitar", "Transferir", "Mitigar"], "Trasladar el impacto financiero a un tercero es transferencia.", ["Aceptar el riesgo significa no tomar ninguna acción y absorber las pérdidas; contratar un seguro es una acción.", "Evitar el riesgo significa detener por completo la actividad riesgosa, no pagar para cubrir sus costos.", null, "Mitigar significa reducir la probabilidad o el impacto con controles; el seguro traslada el impacto financiero en lugar de reducirlo."]],
  "s85": ["Un activo vale $200,000, el factor de exposición es del 25% y la ARO es 0.5. ¿Cuál es la ALE?", ["$25,000", "$50,000", "$100,000", "$12,500"], "SLE = 200,000 × 0.25 = 50,000; ALE = 50,000 × 0.5 = 25,000.", [null, "$50,000 es la SLE (200,000 x 0.25); todavía hay que multiplicarla por la ARO de 0.5.", "$100,000 es el valor del activo multiplicado por la ARO, omitiendo el factor de exposición.", "$12,500 vuelve a dividir a la mitad la respuesta correcta, como si la ARO se aplicara dos veces."]],
  "s86": ["¿Qué acuerdo define el tiempo de actividad y los tiempos de respuesta garantizados de un proveedor?", ["NDA", "SLA", "MOU", "BPA"], "Un acuerdo de nivel de servicio fija metas de desempeño medibles.", ["Un NDA protege la información confidencial compartida entre las partes; no fija tiempos de actividad ni de respuesta.", null, "Un MOU expresa una intención general de cooperar y normalmente no es vinculante, sin metas de desempeño medibles.", "Un BPA fija los términos de una asociación comercial, como el reparto de utilidades, no niveles de servicio garantizados."]],
  "s87": ["Según el GDPR, la organización que decide por qué y cómo se tratan los datos personales es el:", ["Encargado del tratamiento (data processor)", "Responsable del tratamiento (data controller)", "Custodio de datos (data custodian)", "Titular de los datos (data subject)"], "El responsable determina los fines y los medios; el encargado actúa en su nombre.", ["El encargado del tratamiento maneja los datos personales en nombre del responsable y no decide los fines.", null, "El custodio de datos mantiene y protege técnicamente los datos, pero no decide por qué se tratan.", "El titular de los datos es la persona a la que describen los datos personales, no la organización que los trata."]],
  "s88": ["Un documento con instrucciones paso a paso para restablecer el MFA de un usuario es:", ["Una política", "Un estándar", "Un procedimiento", "Una guía"], "Los procedimientos son paso a paso.", ["Una política expresa la intención y las reglas de alto nivel, no instrucciones detalladas paso a paso.", "Un estándar fija requisitos obligatorios, como configuraciones específicas, pero no da la secuencia de pasos.", null, "Una guía da recomendaciones opcionales, no instrucciones obligatorias paso a paso."]],
  "s89": ["¿Dónde se da seguimiento a los riesgos identificados, sus responsables, su probabilidad y su tratamiento?", ["Registro de riesgos", "Inventario de activos", "SLA", "Registro de cambios"], "El registro de riesgos es el documento central de seguimiento.", [null, "Un inventario de activos enumera los activos de hardware, software y datos, no riesgos con responsables y tratamientos.", "Un SLA define compromisos de desempeño del servicio con un proveedor, no el seguimiento interno de riesgos.", "Un registro de cambios documenta los cambios hechos a los sistemas, no los riesgos identificados y su tratamiento."]],
  "s90": ["¿Cuál es el primer paso esencial para proteger los activos de TI de una organización?", ["Implementar antivirus en todos lados", "Identificar y catalogar todos los activos físicos y digitales", "Instalar firewalls", "Capacitar a los empleados"], "No puedes proteger lo que no sabes que tienes.", ["El antivirus es un control de protección, pero no se puede implementar eficazmente sin saber qué activos tienes.", null, "Los firewalls protegen los límites de la red, pero ubicarlos bien depende de conocer primero tus activos.", "La capacitación es importante, pero no va antes de saber qué sistemas y datos necesitan protección."]],
  "s91": ["El equipo de seguridad envía correos de phishing falsos y registra quién hace clic. Esto forma parte de:", ["Las pruebas de penetración", "La capacitación de concientización de seguridad", "El threat hunting", "El escaneo de vulnerabilidades"], "Las simulaciones de phishing miden y mejoran la concientización de los usuarios.", ["Una prueba de penetración evalúa las defensas técnicas de los sistemas y normalmente es un encargo con tiempo limitado, no un programa continuo de tasas de clics.", null, "El threat hunting busca de forma proactiva atacantes ocultos en el entorno, no empleados que hacen clic.", "El escaneo de vulnerabilidades revisa los sistemas en busca de debilidades técnicas, no el comportamiento de los usuarios."]],
  "s92": ["¿Qué tratamiento del riesgo se usa cuando una empresa deja de ofrecer una línea de productos porque su riesgo de seguridad es demasiado alto?", ["Transferir", "Aceptar", "Mitigar", "Evitar"], "Terminar por completo la actividad riesgosa es evitar el riesgo.", ["Transferir traslada el riesgo a alguien más, como una aseguradora, mientras la actividad continúa.", "Aceptar el riesgo significa continuar la actividad y absorber las posibles pérdidas.", "Mitigar significa agregar controles para reducir el riesgo manteniendo la línea de productos.", null]],
  "s93": ["El nivel de riesgo que una organización está dispuesta a asumir para lograr sus objetivos es su:", ["Apetito de riesgo", "Registro de riesgos", "Riesgo residual", "Riesgo inherente"], "El apetito de riesgo es cuánto riesgo aceptará la dirección para lograr sus objetivos; la tolerancia es la variación aceptable alrededor de él.", [null, "El registro de riesgos es un documento que da seguimiento a los riesgos, no una medida de cuánto riesgo asumirá la dirección.", "El riesgo residual es lo que queda después de los controles, no el nivel que la organización está dispuesta a asumir.", "El riesgo inherente es el nivel de riesgo antes de cualquier control, no la disposición de la organización a asumir riesgos."]],
  "s94": ["Después de aplicar nuevos controles, el riesgo que todavía queda se llama:", ["Riesgo inherente", "Riesgo residual", "Riesgo de control", "Apetito de riesgo"], "El riesgo residual es lo que queda después de los controles; el riesgo inherente es el nivel antes de cualquier control.", ["El riesgo inherente es el nivel antes de aplicar cualquier control, no lo que queda después.", null, "El riesgo de control es el riesgo de que los controles no logren prevenir o detectar problemas, no el riesgo que queda después de aplicarlos.", "El apetito de riesgo es cuánto riesgo está dispuesta a asumir la organización, no lo que queda después de los controles."]],
  "s95": ["Una empresa quiere tener el derecho de inspeccionar los controles de seguridad de un proveedor de nube. ¿Qué cláusula del contrato lo otorga?", ["Cláusula de confidencialidad", "Cláusula de derecho de auditoría", "Cláusula de indemnización", "Cláusula de nivel de servicio"], "Una cláusula de derecho de auditoría permite que el cliente evalúe o revise los controles del proveedor.", ["Una cláusula de confidencialidad protege la información confidencial, pero no otorga el derecho de inspeccionar al proveedor.", null, "Una cláusula de indemnización asigna quién paga ciertas pérdidas o reclamaciones; no permite inspecciones.", "Una cláusula de nivel de servicio fija metas de desempeño como el tiempo de actividad, no derechos de auditoría."]],
  "s96": ["¿Qué acuerdo suele fijar los términos generales para trabajos futuros, con los detalles agregados después en declaraciones de trabajo (SOW)?", ["MOU", "NDA", "MSA", "SLA"], "Un acuerdo marco de servicios (MSA) fija los términos generales; cada SOW define un proyecto específico bajo él.", ["Un MOU es una declaración de intención compartida, normalmente no vinculante, no un marco general para futuros trabajos contratados.", "Un NDA cubre solo la confidencialidad y no fija términos generales para proyectos futuros.", null, "Un SLA define métricas específicas de desempeño del servicio, no los términos generales para todos los trabajos futuros."]],
  "s97": ["Un auditor independiente de la empresa evalúa sus controles para un informe que se comparte con los clientes. ¿Qué tipo de evaluación es esta?", ["Autoevaluación interna", "Auditoría externa (de terceros)", "Ejercicio de mesa", "Escaneo de vulnerabilidades"], "Que una parte externa independiente realice la revisión es una auditoría externa.", ["Una autoevaluación la realiza el propio personal de la empresa, así que no es independiente.", null, "Un ejercicio de mesa es un recorrido de incidentes basado en discusión, no una evaluación independiente de los controles.", "Un escaneo de vulnerabilidades es una verificación técnica automatizada, no una revisión independiente de los controles de la empresa."]],
  "s98": ["¿Qué documento establece quién puede usar los sistemas de la empresa y qué no puede hacer con ellos?", ["Política de uso aceptable", "Plan de respuesta a incidentes", "Procedimiento de gestión de cambios", "Estándar de retención de datos"], "La AUP define el uso permitido y prohibido de los sistemas de la organización.", [null, "Un plan de respuesta a incidentes describe cómo manejar los incidentes de seguridad, no el uso cotidiano permitido de los sistemas.", "Un procedimiento de gestión de cambios rige cómo se aprueban y realizan los cambios en los sistemas, no cómo los usuarios pueden usarlos.", "Un estándar de retención de datos define cuánto tiempo se conservan los datos, no quién puede usar los sistemas ni cómo."]],
  "s99": ["Un análisis de impacto al negocio determina que la nómina debe restaurarse en un plazo de 8 horas. Este valor es el:", ["RPO", "MTBF", "RTO", "ARO"], "El objetivo de tiempo de recuperación es el tiempo máximo aceptable para restaurar una función.", ["El RPO mide la pérdida de datos aceptable en tiempo, no qué tan rápido debe restaurarse una función.", "El MTBF es el tiempo promedio entre fallas, una medida de confiabilidad, no una meta de restauración.", null, "La ARO es con qué frecuencia se espera que ocurra un riesgo cada año, no un tiempo de recuperación."]],
  "s100": ["A un pentester no se le dice nada de antemano sobre el entorno objetivo. ¿Qué tipo de prueba es esta?", ["Entorno conocido", "Entorno parcialmente conocido", "Entorno desconocido", "Prueba integrada"], "Una prueba de entorno desconocido (caja negra) comienza sin información previa.", ["Una prueba de entorno conocido (caja blanca) le da al tester toda la información de antemano.", "Una prueba de entorno parcialmente conocido (caja gris) le da al tester algo de información, como credenciales o diagramas de red.", null, "Una prueba integrada combina actividades o equipos de prueba; no describe cuánto sabe el tester."]],
  "s101": ["¿El incumplimiento de qué obligación es MÁS probable que resulte en multas y sanciones de un regulador?", ["Las guías de estilo internas", "El cumplimiento de las leyes y regulaciones aplicables", "Un white paper opcional de la industria", "Las afirmaciones de marketing de un proveedor"], "El incumplimiento de requisitos legales o regulatorios conlleva multas, sanciones y daño a la reputación.", ["Las guías de estilo internas son convenciones voluntarias de la empresa; ningún regulador las hace cumplir.", null, "Un white paper opcional es solo orientativo; no seguirlo no conlleva ninguna sanción regulatoria.", "Las afirmaciones de marketing de un proveedor no crean ninguna obligación legal que el cliente deba cumplir."]],
  "x1": ["¿Qué tipo de control proporciona instrucciones u orientación que dirigen el comportamiento esperado, como una política que exige cifrar los datos?", ["Directivo", "Correctivo", "Detectivo", "Compensatorio"], "Un control directivo indica o exige que las personas actúen de cierta manera; los controles correctivos reparan el daño después de un evento.", [null, "Los controles correctivos reparan o restauran después de un incidente, no indican el comportamiento de antemano.", "Los controles detectivos identifican que algo ocurrió; no dirigen el comportamiento.", "Un control compensatorio sustituye a un control faltante, no es una instrucción de orientación."]],
  "x2": ["Un parche de seguridad obligatorio no se puede instalar en un sistema heredado, así que el equipo aísla el host y agrega monitoreo adicional en su lugar. ¿Qué son estas medidas sustitutas?", ["Preventivas", "Compensatorias", "Detectivas", "Disuasivas"], "Los controles que se usan en lugar de uno obligatorio que no se puede cumplir son controles compensatorios; compensan la salvaguarda faltante.", ["Los controles preventivos detienen un incidente directamente; aquí no se pudo aplicar el control obligatorio.", null, "Los controles detectivos solo identifican eventos; no sustituyen una salvaguarda faltante.", "Los controles disuasivos desalientan una acción; no sustituyen a un control no disponible."]],
  "x3": ["¿Qué algoritmo permite que dos partes acuerden un secreto compartido a través de una red no confiable sin transmitir nunca la clave en sí?", ["AES", "SHA-256", "Diffie-Hellman", "Firma con RSA"], "Diffie-Hellman es un método de intercambio de claves para derivar un secreto compartido; AES es cifrado simétrico y SHA-256 es hashing.", ["AES es un cifrado simétrico y requiere que la clave compartida ya se conozca.", "SHA-256 es un hash unidireccional y no puede establecer un secreto compartido.", null, "La firma con RSA proporciona autenticación e integridad, no un acuerdo de clave de secreto compartido."]],
  "x4": ["Una base de datos de pruebas muestra los nombres de los clientes como XXXX y solo los últimos cuatro dígitos de cada número de cuenta. ¿Qué técnica es esta?", ["Tokenización", "Enmascaramiento de datos", "Hashing", "Key escrow"], "El enmascaramiento oculta parte de un valor manteniéndolo utilizable para pruebas; la tokenización reemplaza el valor completo mediante una bóveda.", ["La tokenización reemplaza el valor completo con un token asociado en una bóveda, no lo muestra parcialmente.", null, "El hashing es unidireccional y produce un resumen ilegible, no un valor mostrado parcialmente.", "El key escrow guarda claves para su recuperación y no tiene nada que ver con cómo se muestran los datos."]],
  "x5": ["Roban una laptop mientras está apagada. ¿Qué control protege MEJOR todos los datos de su disco contra la lectura?", ["Cifrado a nivel de archivo de una carpeta", "Cifrado de disco completo", "Protector de pantalla con contraseña", "Aplicar hash a los archivos"], "El cifrado de disco completo protege toda la unidad en reposo; cifrar una carpeta deja expuestos otros datos y un protector de pantalla no protege el disco.", ["Cifrar una carpeta deja legible el resto de la unidad si la roban.", null, "La contraseña del protector de pantalla no cifra en absoluto los datos del disco.", "El hashing es una verificación de integridad unidireccional y no protege la confidencialidad de los archivos."]],
  "x6": ["Una organización guarda una copia de sus claves de cifrado con un tercero de confianza para poder recuperar los datos si se pierde una clave. ¿Qué práctica es esta?", ["Key stretching", "Perfect forward secrecy", "Certificate pinning", "Key escrow"], "Guardar claves en reserva para su recuperación es key escrow; el key stretching, en cambio, fortalece contraseñas débiles.", ["El key stretching fortalece contraseñas débiles; no guarda claves recuperables.", "Perfect forward secrecy limita la exposición de sesiones pasadas, no la recuperación de claves.", "El certificate pinning vincula un host a un certificado específico, sin relación con la recuperación de claves.", null]],
  "x7": ["Un atacante oculta datos robados dentro de un archivo de imagen de apariencia normal para que pasen la inspección. ¿Qué técnica es esta?", ["Tokenización", "Esteganografía", "Agregar salt al hash", "Hashing"], "La esteganografía oculta datos dentro de otros datos, como una imagen; la tokenización y el hashing no ocultan datos dentro de archivos.", ["La tokenización cambia datos por tokens; no oculta datos dentro de otro archivo.", null, "Agregar salt añade aleatoriedad al hash de contraseñas; no oculta datos exfiltrados.", "El hashing produce un resumen y no puede incrustar datos dentro de una imagen."]],
  "x8": ["Un usuario escribe mal la dirección web de un banco y llega a un sitio malicioso muy parecido, registrado con ese error ortográfico. ¿Qué es esto?", ["Watering hole", "Pharming", "Typosquatting", "Pretexting"], "Registrar errores ortográficos comunes de un dominio para aprovechar los errores de tipeo es typosquatting; un watering hole compromete un sitio que el objetivo ya visita.", ["Un watering hole compromete un sitio que el objetivo ya visita, no un dominio mal escrito.", "El pharming redirige a los usuarios mediante cambios en DNS o en el archivo hosts, no aprovechando errores de tipeo.", null, "El pretexting consiste en inventar un escenario falso, no en registrar dominios parecidos."]],
  "x9": ["Un atacante captura un token de autenticación válido y lo reenvía más tarde para obtener acceso. ¿Qué ataque es este?", ["Ataque de cumpleaños", "Ataque de degradación", "Ataque de repetición (replay)", "Ataque de colisión"], "Reutilizar datos válidos capturados para volver a autenticarse es un ataque de repetición; una degradación, en cambio, fuerza protocolos más débiles.", ["Un ataque de cumpleaños apunta a colisiones de hash, no a datos de autenticación reutilizados.", "Un ataque de degradación fuerza protocolos más débiles; no reenvía tokens capturados.", null, "Un ataque de colisión encuentra dos entradas con el mismo hash, no credenciales repetidas."]],
  "x10": ["Un atacante construye tramas Ethernet con doble etiqueta para enviar tráfico desde su VLAN hacia una VLAN restringida. ¿Qué es esto?", ["MAC flooding", "Envenenamiento de ARP", "Envenenamiento de DNS", "VLAN hopping"], "El doble etiquetado para llegar a otra VLAN es VLAN hopping; el MAC flooding, en cambio, satura la tabla de direcciones del switch.", ["El MAC flooding satura la tabla del switch; no usa etiquetas VLAN para cruzar entre VLAN.", "El envenenamiento de ARP falsifica asociaciones de IP a MAC en un segmento, no usa etiquetado VLAN.", "El envenenamiento de DNS corrompe la resolución de nombres, sin relación con las etiquetas VLAN.", null]],
  "x11": ["Un atacante satura la tabla de direcciones MAC de un switch para que difunda tramas por todos los puertos, lo que permite capturar el tráfico. ¿Qué ataque es este?", ["Envenenamiento de ARP", "VLAN hopping", "Ataque Smurf", "MAC flooding"], "Llenar la tabla CAM para que el switch falle en modo abierto y difunda el tráfico es MAC flooding; el envenenamiento de ARP, en cambio, falsifica asociaciones de IP a MAC.", ["El envenenamiento de ARP falsifica respuestas de IP a MAC; no desborda la tabla del switch.", "El VLAN hopping cruza los límites entre VLAN; no inunda la tabla MAC.", "Un ataque Smurf es una inundación por amplificación ICMP, no un desbordamiento de la tabla del switch.", null]],
  "x12": ["Unos atacantes prueban en tu página de inicio de sesión pares de usuario y contraseña robados de otro sitio web vulnerado. ¿Qué ataque es este?", ["Password spraying", "Fuerza bruta", "Rainbow table", "Credential stuffing"], "Reutilizar credenciales filtradas de otro lugar es credential stuffing; el spraying prueba unas pocas contraseñas comunes en muchas cuentas.", ["El password spraying usa unas pocas contraseñas comunes en varias cuentas, no pares filtrados.", "La fuerza bruta prueba muchas combinaciones contra una sola cuenta, no datos reutilizados de una brecha.", "Una rainbow table descifra hashes capturados fuera de línea, no reutiliza credenciales en vivo.", null]],
  "x13": ["Un empleado de finanzas recibe un correo que parece ser del CEO y que solicita con urgencia una transferencia bancaria a una cuenta nueva. ¿Qué ataque es este?", ["Watering hole", "Business email compromise (BEC)", "Smishing", "Typosquatting"], "Hacerse pasar por un ejecutivo para autorizar pagos fraudulentos es business email compromise; el smishing usa SMS en lugar de correo.", ["Un watering hole infecta un sitio web de confianza, no es un correo que se hace pasar por el CEO.", null, "El smishing llega por mensaje de texto SMS, no por correo electrónico.", "El typosquatting se basa en dominios mal escritos, no en hacerse pasar por un ejecutivo por correo."]],
  "x14": ["¿Qué ataque criptográfico aprovecha la probabilidad de que dos entradas distintas produzcan el mismo valor hash?", ["Ataque de degradación", "Ataque de repetición", "Ataque de diccionario", "Ataque de colisión"], "Encontrar dos entradas con el mismo hash es un ataque de colisión; una degradación, en cambio, fuerza una criptografía más débil.", ["Un ataque de degradación fuerza una criptografía más débil, no colisiones de hash.", "Un ataque de repetición reenvía datos capturados; no aprovecha colisiones de hash.", "Un ataque de diccionario adivina contraseñas a partir de una lista de palabras, no busca hashes coincidentes.", null]],
  "x15": ["Un atacante corrompe la caché de un resolver para que un nombre de dominio apunte a una IP maliciosa para muchos usuarios. ¿Qué es esto?", ["Envenenamiento de ARP", "Envenenamiento de DNS", "MAC flooding", "Secuestro de sesión"], "Corromper las asociaciones de nombre a IP en caché es envenenamiento de DNS (de caché); el envenenamiento de ARP, en cambio, apunta a las asociaciones locales de IP a MAC.", ["El envenenamiento de ARP apunta a las asociaciones locales de IP a MAC, no a la caché de nombres del resolver.", null, "El MAC flooding satura un switch; no altera registros DNS.", "El secuestro de sesión roba una sesión activa, no entradas de la caché del resolver."]],
  "x16": ["Un malware se propaga por una oficina cuando los empleados conectan memorias USB que encontraron en el estacionamiento. ¿Qué vector de amenaza se está explotando?", ["Correo electrónico", "Cadena de suministro", "Medios extraíbles", "Puerto de servicio abierto"], "Las memorias USB son un vector de medios extraíbles; un ataque a la cadena de suministro comprometería en cambio el producto de un proveedor de confianza.", ["El correo es un vector distinto; aquí el malware llegó en memorias USB físicas.", "Un ataque a la cadena de suministro compromete el producto de un proveedor de confianza, no memorias USB encontradas.", null, "Un puerto de servicio abierto es una exposición de red, no un medio extraíble físico."]],
  "x17": ["Un usuario estándar explota una falla para obtener derechos completos de administrador en el mismo host. ¿Cómo se llama esta actividad?", ["Movimiento lateral", "Escalamiento de privilegios", "Exfiltración de datos", "Persistencia"], "Obtener derechos más altos en un sistema es escalamiento de privilegios; el movimiento lateral, en cambio, se extiende a otros hosts con el mismo nivel.", ["El movimiento lateral se extiende a otros sistemas, no obtiene derechos en el mismo host.", null, "La exfiltración de datos es robar datos, no elevar el nivel de privilegios.", "La persistencia es mantener el acceso a lo largo del tiempo, no elevar los derechos."]],
  "x18": ["Tras una posible brecha, un analista descubre que se eliminaron los logs de seguridad de un periodo de dos horas. ¿Qué indicador de compromiso es este?", ["Viaje imposible", "Logs faltantes", "Bloqueo de cuenta", "Consumo de recursos"], "Las entradas de log eliminadas o ausentes son un indicador de logs faltantes, que a menudo se usa para ocultar actividad; el viaje imposible se refiere a la geografía de los inicios de sesión.", ["El viaje imposible se refiere a inicios de sesión desde lugares distantes, no a logs eliminados.", null, "El bloqueo de cuenta tiene que ver con inicios de sesión fallidos, no con entradas de log faltantes.", "El consumo de recursos es un uso inusual de CPU o ancho de banda, no logs eliminados."]],
  "x19": ["Para reducir el riesgo de una actualización de software manipulada, una empresa confirma la firma criptográfica del proveedor antes de instalarla. ¿Qué mitigación es esta?", ["Segmentación de red", "Enmascaramiento de datos", "Balanceo de carga", "Verificación de la firma de código"], "Verificar la firma de código del proveedor detecta actualizaciones manipuladas; la segmentación y el balanceo de carga no validan la autenticidad del software.", ["La segmentación limita el movimiento, pero no verifica la autenticidad del software.", "El enmascaramiento de datos oculta valores al mostrarlos; no comprueba la integridad de las actualizaciones.", "El balanceo de carga distribuye el tráfico y no valida las firmas del software.", null]],
  "x20": ["Un malware le da a un atacante control remoto interactivo completo del escritorio de una víctima mientras se oculta del usuario. ¿Qué es?", ["Troyano de acceso remoto (RAT)", "Gusano", "Bomba lógica", "Adware"], "Un troyano de acceso remoto (RAT) proporciona control remoto encubierto; un gusano se autorreplica y una bomba lógica se activa con una condición.", [null, "Un gusano se autorreplica a través de las redes; no proporciona control interactivo.", "Una bomba lógica se activa con una condición; no es malware de control remoto.", "El adware muestra anuncios no deseados; no le da a un atacante control del escritorio."]],
  "x21": ["¿Qué tecnología empaqueta una aplicación con sus dependencias para compartir el kernel del sistema operativo del host, a diferencia de una máquina virtual completa?", ["Contenedor", "Hipervisor", "Servidor bare-metal", "RTOS"], "Los contenedores comparten el kernel del host y aíslan a nivel de proceso; un hipervisor ejecuta VM completas, cada una con su propio sistema operativo.", [null, "Un hipervisor ejecuta máquinas virtuales completas, cada una con su propio sistema operativo.", "Un servidor bare-metal es hardware físico, no una aplicación empaquetada ligera.", "Un RTOS es un sistema operativo de tiempo real, no un método para empaquetar aplicaciones."]],
  "x22": ["¿Qué tecnología mantiene funcionando un solo servidor ante la falla de un disco reflejando los datos o distribuyéndolos con paridad entre varias unidades?", ["Balanceo de carga", "Snapshots", "RAID", "Clustering"], "RAID proporciona tolerancia a fallas a nivel de disco dentro de un sistema; el balanceo de carga y el clustering abarcan varios servidores, no la falla de un solo disco.", ["El balanceo de carga distribuye el tráfico entre servidores, no ofrece tolerancia a fallas de disco.", "Un snapshot captura el estado en un momento dado; no sobrevive a la falla de un disco en funcionamiento.", null, "El clustering conmuta entre servidores, no dentro de los discos de un solo servidor."]],
  "x23": ["¿Qué control inspecciona el correo saliente y bloquea los mensajes que contienen números de tarjeta de crédito para que no salgan de la empresa?", ["WAF", "Prevención de pérdida de datos (DLP)", "IPS", "NAC"], "La prevención de pérdida de datos detecta y bloquea la salida de datos sensibles de la organización; un WAF protege las aplicaciones web contra ataques entrantes.", ["Un WAF protege las aplicaciones web contra ataques entrantes, no contra fugas de datos salientes.", null, "Un IPS bloquea intrusiones en la red; no se enfoca en la salida de datos sensibles.", "NAC controla el acceso de los dispositivos a la red, no el contenido del correo saliente."]],
  "x24": ["Asignar etiquetas como público, interno, confidencial y restringido a la información se llama:", ["Enmascaramiento de datos", "Tokenización", "Retención de datos", "Clasificación de datos"], "Etiquetar los datos según su sensibilidad es clasificación de datos; el enmascaramiento y la tokenización, en cambio, ocultan los valores de los datos.", ["El enmascaramiento de datos oculta partes de un valor; no asigna etiquetas de sensibilidad.", "La tokenización cambia valores por tokens en lugar de etiquetar su sensibilidad.", "La retención de datos rige cuánto tiempo se conservan los datos, no su etiquetado por sensibilidad.", null]],
  "x25": ["Antes de permitir que una laptop entre a la red, un sistema verifica que su antivirus y sus parches estén al día y la pone en cuarentena si no lo están. ¿Qué es esto?", ["Control de acceso a la red (NAC)", "Balanceo de carga", "Reenvío de puertos", "Jump server"], "Verificar la postura del dispositivo antes de otorgar acceso a la red es control de acceso a la red (NAC); un jump server es un host de acceso endurecido, no una verificación de postura.", [null, "El balanceo de carga distribuye el tráfico; no verifica la postura de seguridad del dispositivo.", "El reenvío de puertos redirige puertos específicos y no evalúa los endpoints.", "Un jump server es un host de acceso controlado, no un guardián que verifica la postura."]],
  "x26": ["¿Qué suite de protocolos proporciona cifrado y autenticación para una VPN sitio a sitio en la capa de red?", ["TLS", "IPsec", "SSH", "S/MIME"], "IPsec protege el tráfico en la capa de red para las VPN; TLS opera en una capa superior y S/MIME protege específicamente el correo.", ["TLS protege el tráfico en la capa de transporte, no en la capa de red para las VPN.", null, "SSH protege sesiones remotas, no túneles VPN sitio a sitio en general.", "S/MIME protege mensajes de correo, no el tráfico VPN de capa de red."]],
  "x27": ["Una instalación de recuperación que tiene espacio y energía, pero no tiene hardware instalado ni datos actualizados, es un:", ["Hot site", "Warm site", "Cold site", "Sitio móvil"], "Un cold site proporciona solo la instalación básica y debe equiparse antes de usarse; un hot site está totalmente listo con datos actualizados.", ["Un hot site está totalmente equipado con datos actualizados y listo de inmediato.", "Un warm site tiene algo de equipo listo y no está vacío como un cold site.", null, "Un sitio móvil es una instalación transportable, no la opción de solo espacio y energía."]],
  "x28": ["Dos servidores funcionan como clúster para que, si uno falla, el otro tome el control sin pérdida de servicio. Este diseño proporciona:", ["Clasificación de datos", "Mínimo privilegio", "Tokenización", "Alta disponibilidad"], "El clustering para mantener el servicio continuo ante una falla ofrece alta disponibilidad; los demás términos se refieren al acceso o al manejo de datos.", ["La clasificación de datos etiqueta la información; no mantiene un servicio en funcionamiento.", "El mínimo privilegio limita los derechos de acceso, no la continuidad del servicio ante una falla.", "La tokenización protege los valores de los datos, no la disponibilidad durante la falla de un servidor.", null]],
  "x29": ["Una bomba de infusión médica ejecuta un pequeño sistema operativo que garantiza que las tareas se completen dentro de límites de tiempo estrictos. ¿Qué tipo de sistema es este?", ["Hipervisor", "Runtime de contenedores", "SIEM", "Sistema operativo de tiempo real"], "Un sistema operativo que garantiza restricciones de tiempo para dispositivos embebidos es un sistema operativo de tiempo real (RTOS); un hipervisor aloja máquinas virtuales.", ["Un hipervisor aloja máquinas virtuales; no garantiza los tiempos de las tareas.", "Un runtime de contenedores ejecuta contenedores; no ofrece garantías de tiempo real.", "Un SIEM agrega logs y no tiene relación con los tiempos de un dispositivo embebido.", null]],
  "x30": ["Un switch está configurado para permitir solo una dirección MAC específica por puerto de acceso y apagar el puerto si aparece otra. ¿Qué función es esta?", ["Port security", "VLAN hopping", "Spanning tree", "Agregación de enlaces"], "Limitar un puerto a direcciones MAC aprobadas es port security; spanning tree evita bucles y la agregación de enlaces une varios enlaces.", [null, "El VLAN hopping es un ataque, no una función de protección de puertos del switch.", "Spanning tree evita bucles de conmutación, no direcciones MAC no autorizadas.", "La agregación de enlaces une varios enlaces para obtener más ancho de banda, no restringe direcciones MAC."]],
  "x31": ["¿Qué dispositivo se ubica entre los usuarios internos e internet, almacena contenido en caché y filtra a qué sitios pueden acceder los usuarios?", ["Proxy de reenvío (forward proxy)", "Proxy inverso", "Balanceador de carga", "Network tap"], "Un forward proxy intermedia las solicitudes salientes de los usuarios y el filtrado; un proxy inverso, en cambio, está delante de servidores internos para clientes entrantes.", [null, "Un proxy inverso está delante de servidores internos para clientes entrantes, no para usuarios salientes.", "Un balanceador de carga distribuye el tráfico entre servidores, no filtra contenido para los usuarios.", "Un network tap copia el tráfico de forma pasiva; no filtra el acceso web de los usuarios."]],
  "x32": ["¿Qué proceso de operaciones programa, prueba y despliega las actualizaciones de los proveedores para corregir vulnerabilidades en los sistemas?", ["Gestión de parches", "Congelamiento de cambios", "Threat hunting", "Tokenización de datos"], "Aplicar sistemáticamente las correcciones de los proveedores es gestión de parches; un congelamiento de cambios detiene los cambios y el threat hunting busca intrusos.", [null, "Un congelamiento de cambios pausa los cambios; no aplica parches de proveedores.", "El threat hunting busca intrusos, no despliega actualizaciones de proveedores.", "La tokenización de datos protege los valores de los datos y no gestiona parches."]],
  "x33": ["Una empresa exige el bloqueo de pantalla en los teléfonos de los empleados y puede borrarlos de forma remota si se pierden. ¿Qué herramienta proporciona esto?", ["Prevención de pérdida de datos", "SIEM", "Gestión de dispositivos móviles (MDM)", "WAF"], "La gestión de dispositivos móviles aplica políticas y el borrado remoto en los dispositivos; DLP se enfoca en impedir la salida de datos, no en controlar dispositivos.", ["La prevención de pérdida de datos impide la salida de datos sensibles, no aplica políticas al dispositivo ni lo borra.", "Un SIEM correlaciona logs; no exige bloqueos de teléfono ni borrado remoto.", null, "Un WAF protege aplicaciones web, no la configuración de dispositivos móviles."]],
  "x34": ["¿Qué control de correo basado en DNS enumera los servidores de correo autorizados para enviar correo en nombre de un dominio?", ["DKIM", "DMARC", "SPF", "DNSSEC"], "SPF publica los servidores de envío autorizados de un dominio; DKIM firma los mensajes y DMARC fija la política cuando fallan las verificaciones.", ["DKIM firma los mensajes para la integridad; no enumera los remitentes autorizados.", "DMARC fija la política para manejar las fallas, no la lista de servidores autorizados.", null, "DNSSEC firma los registros DNS para la integridad, no autoriza a los remitentes de correo."]],
  "x35": ["¿Qué control de correo agrega una firma criptográfica a los mensajes salientes para que los receptores puedan verificar que no se alteraron en tránsito?", ["SPF", "DKIM", "TLS", "DNSSEC"], "DKIM firma los mensajes para poder verificar su integridad y origen; SPF solo enumera los remitentes autorizados y no firma el contenido.", ["SPF enumera los servidores de envío autorizados, pero no firma el contenido del mensaje.", null, "TLS cifra la conexión en tránsito, pero no firma el mensaje en sí.", "DNSSEC protege los registros DNS, no la integridad de los mensajes de correo individuales."]],
  "x36": ["Un empleado inicia sesión en varias aplicaciones en la nube a través del proveedor de identidad de la empresa usando aserciones XML firmadas para el inicio de sesión único. ¿Qué estándar es este?", ["OAuth", "RADIUS", "TACACS+", "SAML"], "SAML usa aserciones XML firmadas para el inicio de sesión único federado; OAuth es autorización delegada y no usa aserciones SAML.", ["OAuth proporciona autorización delegada y no usa aserciones XML firmadas.", "RADIUS es un protocolo de autenticación de red, no SSO federado con aserciones.", "TACACS+ maneja la autenticación para la administración de dispositivos, no el SSO web con SAML.", null]],
  "x37": ["Un inicio de sesión requiere una contraseña más un código de un solo uso de una aplicación autenticadora. ¿Cuántos tipos distintos de factores de autenticación se usan?", ["Uno", "Dos", "Tres", "Cuatro"], "Una contraseña es algo que sabes y el código de la aplicación es algo que tienes, así que se usan dos tipos de factores.", ["Una contraseña y un código de aplicación son dos tipos de factores diferentes, no uno.", null, "Solo hay dos tipos de factores presentes, no tres.", "Solo hay dos tipos de factores presentes, no cuatro."]],
  "x38": ["Los analistas buscan de forma proactiva en el entorno señales de atacantes no detectados a partir de una hipótesis, en lugar de esperar alertas. Esto es:", ["Threat hunting", "Escaneo de vulnerabilidades", "Prueba de penetración", "Gestión de parches"], "La búsqueda de intrusos ocultos guiada por hipótesis es threat hunting; el escaneo de vulnerabilidades solo busca debilidades conocidas.", [null, "El escaneo de vulnerabilidades busca debilidades conocidas, no intrusos ocultos activos.", "Las pruebas de penetración simulan ataques dentro de un alcance definido, no son una búsqueda continua guiada por hipótesis.", "La gestión de parches despliega correcciones y no busca atacantes."]],
  "x39": ["¿Qué control alerta a los administradores cuando los archivos críticos del sistema se modifican de forma inesperada?", ["Balanceo de carga", "Enmascaramiento de datos", "Port security", "Monitoreo de integridad de archivos (FIM)"], "El monitoreo de integridad de archivos detecta cambios inesperados en archivos importantes; las demás opciones no vigilan el contenido de los archivos.", ["El balanceo de carga distribuye el tráfico; no monitorea cambios en archivos.", "El enmascaramiento de datos oculta valores al mostrarlos, no detecta modificaciones de archivos.", "Port security restringe direcciones MAC en los puertos del switch, no cambios en archivos.", null]],
  "x40": ["Después de eliminar el malware y restaurar los sistemas desde respaldos limpios, los usuarios vuelven a estar en línea bajo un monitoreo estrecho. ¿Qué fase de respuesta a incidentes es esta?", ["Contención", "Erradicación", "Recuperación", "Preparación"], "Devolver los sistemas a la operación normal y monitorearlos es la fase de recuperación; la erradicación es la eliminación previa de la amenaza.", ["La contención limita la propagación del incidente antes de la eliminación, lo cual ocurre antes.", "La erradicación elimina la amenaza y la causa raíz, lo cual ya ocurrió aquí.", null, "La preparación ocurre antes de cualquier incidente, no mientras se restablece el servicio."]],
  "x41": ["Durante un incidente, un analista necesita ver el contenido exacto del tráfico de red. ¿Qué fuente de datos es la MÁS útil?", ["Captura completa de paquetes", "Logs de temperatura de la CPU", "Logs de acceso con credenciales", "Registros de licencias de software"], "La captura completa de paquetes conserva el contenido real del tráfico para su análisis; los registros de temperatura y de licencias no revelan nada sobre el tráfico.", [null, "Los logs de temperatura de la CPU revelan condiciones del hardware, no el contenido del tráfico.", "Los logs de acceso con credenciales muestran las entradas físicas, no el contenido de los paquetes de red.", "Los registros de licencias dan seguimiento a los derechos de uso del software, no al tráfico de red."]],
  "x42": ["¿Cuál es el beneficio principal de automatizar el triaje repetitivo de alertas con un playbook de SOAR?", ["Una respuesta más rápida y consistente con menos esfuerzo de los analistas", "Elimina la necesidad de cualquier registro", "Garantiza cero falsos positivos", "Reemplaza al firewall"], "La automatización da respuestas más rápidas y consistentes y libera a los analistas; no elimina el registro ni los falsos positivos.", [null, "La automatización sigue dependiendo del registro; no elimina la necesidad de logs.", "Ninguna automatización puede garantizar cero falsos positivos.", "Una plataforma SOAR orquesta la respuesta y no reemplaza a un firewall."]],
  "x43": ["Un escaneo de vulnerabilidades devuelve cientos de hallazgos. ¿Cuál se debe corregir PRIMERO por lo general?", ["Hallazgos informativos en servidores de prueba", "Los hallazgos más antiguos, sin importar su severidad", "Vulnerabilidades críticas en sistemas expuestos a internet", "Problemas de baja severidad en hosts aislados"], "Las fallas críticas en sistemas expuestos a internet conllevan el mayor riesgo y se priorizan; la antigüedad y los problemas de baja severidad vienen después.", ["Los hallazgos informativos en sistemas de prueba son la prioridad más baja, no la primera.", "Corregir solo por antigüedad ignora la severidad y la exposición, que son las que determinan el riesgo.", null, "Los problemas de baja severidad en hosts aislados representan poco riesgo y vienen después."]],
  "x44": ["¿Qué herramienta ayuda a los usuarios a usar una contraseña única y robusta para cada cuenta sin tener que memorizarlas todas?", ["Gestor de contraseñas", "Servicio de key escrow", "SIEM", "Honeypot"], "Un gestor de contraseñas almacena y genera de forma segura credenciales únicas; el key escrow guarda claves de cifrado, no contraseñas de usuarios.", [null, "El key escrow guarda claves de cifrado para su recuperación, no contraseñas de cuentas de usuario.", "Un SIEM correlaciona logs de seguridad y no gestiona contraseñas de usuarios.", "Un honeypot es un sistema señuelo, no una herramienta para almacenar contraseñas."]],
  "x45": ["¿Contra qué ataque defiende principalmente bloquear una cuenta después de cinco intentos fallidos consecutivos de inicio de sesión?", ["Phishing", "Exfiltración de datos", "Adivinación por fuerza bruta en línea", "Inyección SQL"], "Los bloqueos detienen la adivinación repetida de contraseñas en línea; el phishing y la inyección SQL no dependen de muchos intentos de inicio de sesión.", ["El phishing engaña a los usuarios para que revelen datos; los bloqueos no lo detienen.", "La exfiltración de datos es robar datos, no intentos repetidos de inicio de sesión.", null, "La inyección SQL abusa de los campos de entrada, no de intentos repetidos de inicio de sesión."]],
  "x46": ["Un registro falso de base de datos que genera una alerta si alguien accede a él es un ejemplo de:", ["Balanceador de carga", "Salt", "Tokenización", "Honeytoken"], "Un elemento de datos señuelo que alerta cuando se accede a él es un honeytoken; un salt fortalece el hash de contraseñas y no tiene relación.", ["Un balanceador de carga distribuye el tráfico y no es un elemento señuelo que genere alertas.", "Un salt agrega aleatoriedad al hash de contraseñas, no es un registro señuelo.", "La tokenización reemplaza datos con tokens; no es un señuelo que genere alertas.", null]],
  "x47": ["Una política móvil impide que una aplicación corporativa se ejecute cuando el dispositivo sale de un área geográfica definida. ¿Qué función es esta?", ["Geofencing (geocerca)", "Contenerización", "Cifrado de disco completo", "Tokenización"], "Restringir el comportamiento según la ubicación física es geofencing; la contenerización, en cambio, separa los datos laborales de los personales.", [null, "La contenerización separa los datos laborales de los personales, no bloquea según la ubicación.", "El cifrado de disco completo protege los datos en reposo, no el uso de aplicaciones según la ubicación.", "La tokenización protege los valores de los datos y no restringe según la ubicación."]],
  "x48": ["Un sistema de monitoreo no genera una alerta ante un ataque que realmente ocurrió. Esta detección omitida es un:", ["Falso positivo", "Falso negativo", "Verdadero positivo", "Verdadero negativo"], "Un evento real que no se detecta es un falso negativo; un falso positivo es una alerta por algo que no ocurrió.", ["Un falso positivo es una alerta por algo que en realidad no ocurrió.", null, "Un verdadero positivo es una alerta correcta ante un evento real, no una omisión.", "Un verdadero negativo es no alertar correctamente cuando no ocurrió nada."]],
  "x49": ["¿Quién es el responsable de clasificar un conjunto de datos y decidir quién puede acceder a él?", ["Custodio de datos", "Titular de los datos", "Dueño de los datos (data owner)", "Encargado del tratamiento"], "El dueño de los datos responde por las decisiones de clasificación y acceso; el custodio solo implementa los controles que el dueño indica.", ["El custodio de datos implementa los controles, pero no es responsable de la clasificación.", "El titular de los datos es la persona sobre la que tratan los datos, no quien los clasifica.", null, "El encargado del tratamiento actúa según las instrucciones del responsable, no clasifica el acceso."]],
  "x50": ["¿Quién es responsable de implementar y mantener los controles de protección de los datos según lo indique su dueño?", ["Dueño de los datos", "Custodio de datos (data custodian)", "Responsable del tratamiento", "Regulador"], "El custodio de datos lleva a cabo la protección que especifica el dueño; el dueño fija los requisitos, pero no hace el trabajo práctico.", ["El dueño de los datos fija los requisitos, pero no realiza la protección práctica.", null, "El responsable del tratamiento decide los fines y los medios, no el mantenimiento diario de los controles.", "Un regulador hace cumplir las leyes y no mantiene los controles de una organización."]],
  "x51": ["Una métrica que da una alerta temprana de que la exposición al riesgo está aumentando, como la cantidad de parches críticos vencidos, es un:", ["Indicador clave de desempeño", "Objetivo de nivel de servicio", "Objetivo de punto de recuperación", "Indicador clave de riesgo"], "Un indicador clave de riesgo señala un riesgo creciente; un indicador clave de desempeño, en cambio, mide el avance hacia una meta.", ["Un indicador clave de desempeño mide el avance hacia una meta, no un riesgo creciente.", "Un objetivo de nivel de servicio es una meta de desempeño del servicio, no una alerta de riesgo.", "Un objetivo de punto de recuperación es la pérdida de datos aceptable, no una métrica de alerta de riesgo.", null]],
  "x52": ["Una evaluación de riesgos califica cada riesgo como bajo, medio o alto según el criterio de expertos en lugar de cifras en dólares. Este enfoque es:", ["Cuantitativo", "Cualitativo", "Actuarial", "Probabilístico"], "Calificar los riesgos con niveles descriptivos es un análisis cualitativo; un enfoque cuantitativo asignaría valores monetarios como la ALE.", ["El análisis cuantitativo usa valores monetarios, no calificaciones descriptivas.", null, "Los métodos actuariales usan datos estadísticos de pérdidas, no simples calificaciones de alto o bajo.", "El análisis probabilístico modela las probabilidades de forma numérica, no con niveles descriptivos."]],
  "x53": ["Antes de adquirir una empresa, una firma revisa su postura de seguridad, su historial de brechas y su cumplimiento. Esta investigación se describe MEJOR como:", ["Due diligence (debida diligencia)", "Due care (debido cuidado)", "Separación de funciones", "Gestión de cambios"], "Investigar antes de tomar una decisión es due diligence; due care es el acto continuo de mantener salvaguardas razonables después.", [null, "Due care es mantener salvaguardas razonables a lo largo del tiempo, no la revisión previa a la decisión.", "La separación de funciones divide tareas entre personas, sin relación con la revisión de una adquisición.", "La gestión de cambios rige los cambios en los sistemas, no la investigación de una adquisición."]],
  "x54": ["Un proveedor de nube entrega un informe de un auditor independiente que da fe de sus controles de seguridad durante un periodo. ¿Qué documento es este?", ["Un folleto de marketing", "Una política de uso aceptable", "Un informe de atestación de terceros", "Una solicitud de cambio"], "El informe de un auditor independiente sobre los controles de un proveedor es una atestación de terceros; una política de uso aceptable rige el uso interno de los sistemas.", ["Un folleto de marketing es material promocional, no un informe de auditoría independiente.", "Una política de uso aceptable rige el uso interno de los sistemas, no la atestación de los controles de un proveedor.", null, "Una solicitud de cambio propone un cambio en un sistema, no es una auditoría de los controles de un proveedor."]],
  "x55": ["El nombre completo de un cliente combinado con su número de Seguro Social es un ejemplo de:", ["Información de identificación personal", "Propiedad intelectual", "Datos públicos", "Datos de telemetría"], "Los datos que identifican a una persona específica son información de identificación personal (PII); la propiedad intelectual son creaciones propias, no datos de identidad.", [null, "La propiedad intelectual son creaciones propias, no datos de identidad personal.", "Los datos públicos están disponibles abiertamente y no son información de identidad sensible.", "Los datos de telemetría son mediciones operativas, no datos personales que identifiquen a alguien."]],
  "x56": ["Antes de incorporar a un proveedor SaaS, una empresa le envía un cuestionario de seguridad y revisa sus certificaciones. Esto forma parte de:", ["La respuesta a incidentes", "La gestión de cambios", "El threat hunting", "La gestión de riesgos de proveedores (terceros)"], "Evaluar la seguridad de un proveedor antes de contratarlo es gestión de riesgos de proveedores; la respuesta a incidentes se ocupa de eventos de seguridad activos.", ["La respuesta a incidentes maneja eventos de seguridad activos, no la revisión de un proveedor antes de incorporarlo.", "La gestión de cambios rige los cambios en los sistemas, no la evaluación de seguridad de proveedores.", "El threat hunting busca intrusos, no evalúa a un posible proveedor.", null]],
  "x57": ["Una regla que exige que todas las contraseñas tengan al menos 14 caracteres se clasifica MEJOR como:", ["Una guía", "Una política", "Un procedimiento", "Un estándar"], "Un requisito obligatorio específico, como una longitud mínima, es un estándar; una política expresa una intención de más alto nivel y una guía es opcional.", ["Una guía es una recomendación opcional, no un requisito obligatorio.", "Una política expresa una intención de alto nivel, no un requisito específico y medible.", "Un procedimiento da instrucciones paso a paso, no una sola regla obligatoria.", null]],
  "x58": ["Una regulación exige conservar los registros de transacciones durante cinco años antes de eliminarlos. Una política que fija este plazo se refiere a:", ["Enmascaramiento de datos", "Clasificación de datos", "Retención de datos", "Tokenización"], "Definir cuánto tiempo se conservan los datos antes de desecharlos es retención de datos; la clasificación, en cambio, etiqueta los datos según su sensibilidad.", ["El enmascaramiento de datos oculta valores al mostrarlos y no fija plazos de conservación y eliminación.", "La clasificación de datos etiqueta la sensibilidad, no cuánto tiempo se conservan los datos.", null, "La tokenización reemplaza valores con tokens, sin relación con los periodos de retención."]],
  "x59": ["Antes de una prueba de penetración, ambas partes firman un documento que define el alcance, los horarios y las técnicas permitidas. Estas son las:", ["Reglas de enfrentamiento (rules of engagement)", "Acuerdo de nivel de servicio", "Cadena de custodia", "Registro de riesgos"], "Las reglas de enfrentamiento fijan los límites de una prueba de penetración; un SLA define metas de desempeño del servicio, no el alcance de la prueba.", [null, "Un acuerdo de nivel de servicio define metas de desempeño, no el alcance ni los límites de la prueba.", "La cadena de custodia da seguimiento al manejo de la evidencia, no a los límites de una prueba de penetración.", "Un registro de riesgos enumera riesgos y responsables, no el alcance de una prueba de seguridad."]],
  "x60": ["Según las regulaciones de privacidad, la persona cuyos datos personales se están tratando es el:", ["Responsable del tratamiento", "Encargado del tratamiento", "Titular de los datos (data subject)", "Custodio de datos"], "La persona sobre la que tratan los datos personales es el titular de los datos; el responsable decide cómo y por qué se tratan los datos.", ["El responsable del tratamiento decide cómo y por qué se tratan los datos, no es la persona.", "El encargado del tratamiento actúa en nombre del responsable, no es la persona descrita.", null, "El custodio de datos mantiene los controles; no es la persona a la que pertenecen los datos."]]
});
